window.__OPENSTAX_PHYSICS__[16] = {"schemaVersion":"4.0.0-physics","generatedAt":"2026-11-27T01:44:27.395Z","number":16,"code":"ch16","slug":"mirrors-and-lenses","title":"Mirrors and Lenses","titleVi":"Gương Cầu & Thấu Kính (Mirrors & Lenses)","sections":[{"uid":"hsphys.ch16.sec00","moduleId":"m54366","number":"16.0","slug":"introduction","title":"Introduction","isIntroduction":true,"learningObjectives":[],"bilingualGuide":null,"keyEquations":[],"subsections":[{"uid":"hsphys.ch16.sec00.sub01","title":"Chapter Introduction","summaryVi":"Tổng quan mở đầu chương: Gương Cầu & Thấu Kính (Mirrors & Lenses) — giới thiệu hiện tượng thực tế và các câu hỏi nền tảng trước khi đi vào định luật chi tiết.","paragraphs":["In another moment Alice was through the glass, and had jumped lightly down into the Looking-glass room.","—Through the Looking Glass by Lewis Carol","Through the Looking Glass tells of the adventures of Alice after she steps from the real world, through a mirror, and into the virtual world. In this chapter we examine the optical meanings of real and virtual, as well as other concepts that make up the field of optics.","The light from this page or screen is formed into an image by the lens of your eyes, much as the lens of the camera that made the photograph at the beginning of this chapter. Mirrors, like lenses, can also form images, which in turn are captured by your eyes.","Optics is the branch of physics that deals with the behavior of visible light and other electromagnetic waves. For now, we concentrate on the propagation of light and its interaction with matter.","It is convenient to divide optics into two major parts based on the size of objects that light encounters. When light interacts with an object that is several times as large as the light’s wavelength, its observable behavior is similar to a ray; it does not display its wave characteristics prominently. We call this part of optics geometric optics . This chapter focuses on situations for which geometric optics is suited."],"figures":[{"sourceId":"fs-id1167065878165","filename":"CNX_HSPhysics_16_00_reflect.jpg","relativePath":"media/CNX_HSPhysics_16_00_reflect.jpg","alt":"A scientist is holding a flashlight and is bending over a mirror to examine its surface. The mirror is reflecting the image of the scientist and his fellow coworkers.[/Figure][S1-LO1]"}],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":[],"glossary":[],"assessments":[],"stats":{"learningObjectiveCount":0,"keyEquationCount":0,"subsectionCount":1,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":0,"assessmentCount":0}},{"uid":"hsphys.ch16.sec01","moduleId":"m54357","number":"16.1","slug":"reflection","title":"Reflection","isIntroduction":false,"learningObjectives":["Explain reflection from mirrors, describe image formation as a consequence of reflection from mirrors, apply ray diagrams to predict and interpret image and object locations, and describe applications of mirrors","Perform calculations based on the law of reflection and the equations for curved mirrors"],"bilingualGuide":{"notebookSummaryVi":"Định luật Phản xạ (θ_i = θ_r), Gương cầu lõm (f > 0), Gương cầu lồi (f < 0), Công thức gương 1/f = 1/d_o + 1/d_i và Độ phóng đại m = -d_i / d_o.","wordProblemCues":[{"phraseEn":"mirror equation & magnification","meaningVi":"Công thức gương & Độ phóng đại","mathNotation":"1/f = 1/d_o + 1/d_i"}],"commonTrapsVi":["Quy ước dấu: Ảnh thật d_i > 0 (ngược chiều, m < 0); Ảnh ảo d_i < 0 (cùng chiều, m > 0)!"]},"keyEquations":[{"name":"lens/mirror equation (reciprocal version)","formula":"\\(\\frac{1}{f} = \\frac{1}{{d}_{i}} + \\frac{1}{{d}_{o}}\\)"},{"name":"lens/mirror equation (solved version)","formula":"\\(f = \\frac{{d}_{i}{d}_{o}}{{d}_{o} + {d}_{i}}\\)"},{"name":"magnification equation","formula":"\\(m = \\frac{{h}_{i}}{{h}_{o}} = \\frac{- {d}_{i}}{{d}_{o}}\\)"},{"name":"radius/focal length equation","formula":"R = 2 f"}],"subsections":[{"uid":"hsphys.ch16.sec01.sub01","title":"Characteristics of Mirrors","summaryVi":"Định luật Phản xạ (θ_i = θ_r), Gương cầu lõm (f > 0), Gương cầu lồi (f < 0), Công thức gương 1/f = 1/d_o + 1/d_i và Độ phóng đại m = -d_i / d_o. Thuật ngữ trọng tâm trong mục này: angle of incidence (Góc tới (θ_i)), angle of reflection (Góc phản xạ (θ_r)), central axis (Trục chính (quang trục)), concave mirror (Gương cầu lõm (Gương hội tụ)).","paragraphs":["There are three ways, as shown in Figure 16.1, in which light can travel from a source to another location. It can come directly from the source through empty space, such as from the Sun to Earth. Light can travel to an object through various media, such as air and glass. Light can also arrive at an object after being reflected, such as by a mirror. In all these cases, light is modeled as traveling in a straight line, called a ray . Light may change direction when it encounters the surface of a different material (such as a mirror) or when it passes from one material to another (such as when passing from air into glass). It then continues in a straight line—that is, as a ray. The word ray comes from mathematics. Here it means a straight line that originates from some point. It is acceptable to visualize light rays as laser rays (or even science fiction depictions of ray guns ).","Because light moves in straight lines, that is, as rays, and changes directions when it interacts with matter, it can be described through geometry and trigonometry. This part of optics, described by straight lines and angles, is therefore called geometric optics . There are two laws that govern how light changes direction when it interacts with matter: the law of reflection , for situations in which light bounces off matter; and the law of refraction , for situations in which light passes through matter. In this section, we consider the geometric optics of reflection .","Whenever we look into a mirror or squint at sunlight glinting from a lake, we are seeing a reflection. How does the reflected light travel from the object to your eyes? The law of reflection states: The angle of reflection , \\({\\theta}_{\\text{r}}\\), equals the angle of incidence , \\({\\theta}_{\\text{i}}\\)\n. This law governs the behavior of all waves when they interact with a smooth surface, and therefore describe the behavior of light waves as well. The reflection of light is simplified when light is treated as a ray. This concept is illustrated in Figure 16.1, which also shows how the angles are measured relative to the line perpendicular to the surface at the point where the light ray strikes it. This perpendicular line is also called the normal line , or just the normal . Light reflected in this way is referred to as specular (from the Latin word for mirror : speculum ).","We expect to see reflections from smooth surfaces, but Figure 16.1, illustrates how a rough surface reflects light. Because the light is reflected from different parts of the surface at different angles, the rays go in many different directions, so the reflected light is diffused . Diffused light allows you to read a printed page from almost any angle because some of the rays go in different directions. Many objects, such as people, clothing, leaves, and walls, have rough surfaces and can be seen from many angles. A mirror, on the other hand, has a smooth surface and reflects light at specific angles.","When we see ourselves in a mirror, it appears that our image is actually behind the mirror. We see the light coming from a direction determined by the law of reflection. The angles are such that our image is exactly the same distance behind the mirror, d i , as the distance we stand away from the mirror, d o . Although these mirror images make objects appear to be where they cannot be (such as behind a solid wall), the images are not figments of our imagination. Mirror images can be photographed and videotaped by instruments and look just as they do to our eyes, which are themselves optical instruments. An image in a mirror is said to be a virtual image , as opposed to a real image . A virtual image is formed when light rays appear to diverge from a point without actually doing so.","Figure 16.1 helps illustrate how a flat mirror forms an image. Two rays are shown emerging from the same point, striking the mirror, and reflecting into the observer’s eye. The rays can diverge slightly, and both still enter the eye. If the rays are extrapolated backward, they seem to originate from a common point behind the mirror, allowing us to locate the image. The paths of the reflected rays into the eye are the same as if they had come directly from that point behind the mirror. Using the law of reflection—the angle of reflection equals the angle of incidence—we can see that the image and object are the same distance from the mirror. This is a virtual image, as defined earlier.","Figure 16.1 is a chase scene from an old silent film called The Circus , starring Charlie Chaplin. The chase scene takes place in a mirror maze. You may have seen such a maze at an amusement park or carnival. Finding your way through the maze can be very difficult. Keep in mind that only one image in the picture is real—the others are virtual.","One of the earliest uses of mirrors for creating the illusion of space is seen in the Palace of Versailles, the former home of French royalty. Construction of the Hall of Mirrors (Figure 16.1) began in 1678. It is still one of the most popular tourist attractions at Versailles.","Only one Charlie in this image (the figure/table) is real. The others are all virtual images of him. Can you tell which is real? Hint—His hat is tilted to one side.","Some mirrors are curved instead of flat. A mirror that curves inward is called a concave mirror , whereas one that curves outward is called a convex mirror . Pick up a well-polished metal spoon and you can see an example of each type of curvature. The side of the spoon that holds the food is a concave mirror; the back of the spoon is a convex mirror. Observe your image on both sides of the spoon.","Ray diagrams can be used to find the point where reflected rays converge or appear to converge, or the point from which rays appear to diverge. This is called the focal point , F. The distance from F to the mirror along the central axis (the line perpendicular to the center of the mirror’s surface) is called the focal length , f . Figure 16.1 shows the focal points of concave and convex mirrors.","Images formed by a concave mirror vary, depending on which side of the focal point the object is placed. For any object placed on the far side of the focal point with respect to the mirror, the rays converge in front of the mirror to form a real image, which can be projected onto a surface, such as a screen or sheet of paper However, for an object located inside the focal point with respect to the concave mirror, the image is virtual. For a convex mirror the image is always virtual—that is, it appears to be behind the mirror. The ray diagrams in Figure 16.1 show how to determine the nature of the image formed by concave and convex mirrors.","The information in Figure 16.1 is summarized in the table below.","You should be able to notice everyday applications of curved mirrors. One common example is the use of security mirrors in stores, as shown in Figure 16.1.","Some telescopes also use curved mirrors and no lenses (except in the eyepieces) both to magnify images and to change the path of light. Figure 16.1 shows a Schmidt-Cassegrain telescope. This design uses a spherical primary concave mirror and a convex secondary mirror. The image is projected onto the focal plane by light passing through the perforated primary mirror. The effective focal length of such a telescope is the focal length of the primary mirror multiplied by the magnification of the secondary mirror. The result is a telescope with a focal length much greater than the length of the telescope itself.","A parabolic concave mirror has the very useful property that all light from a distant source, on reflection by the mirror surface, is directed to the focal point. Likewise, a light source placed at the focal point directs all the light it emits in parallel lines away from the mirror. This case is illustrated by the ray diagram in Figure 16.1. The light source in a car headlight, for example, is located at the focal point of a parabolic mirror.","Parabolic mirrors are also used to collect sunlight and direct it to a focal point, where it is transformed into heat, which in turn can be used to generate electricity. This application is shown in Figure 16.1."],"figures":[{"sourceId":"fs-id1167063589240","filename":"CNX_HSPhysics_16_01_Ray.jpg","relativePath":"media/CNX_HSPhysics_16_01_Ray.jpg","alt":"In view (a), a cartoon image of Earth contains a house superimposed over North America. The Sun is included above and to the right of Earth. An arrow points from the Sun’s rays to a series of lines, which represent Earth’s atmosphere, directly above the Earth. In view (b), a woman is looking out of a window at her car. Arrows show the Sun’s rays bouncing off the car and traveling as light toward the woman."},{"sourceId":"fs-id1167067107661","filename":"CNX_HSPhysics_16_01_Reflect.jpg","relativePath":"media/CNX_HSPhysics_16_01_Reflect.jpg","alt":"A smooth, flat reflective surface is shown. A dotted line drops from the top of the figure and ends when it reaches the smooth surface. This line is perpendicular to the surface; there is a 90° angle between the surface and the perpendicular line. To the left of the perpendicular line, a ray (called an “incident ray” strikes the surface at a 45° angle. This ray—the “reflective ray”—is reflected off the surface to the right of the perpendicular line, again at a 45° angle. The angle between the incident ray and the perpendicular line is θi; the angle between the perpendicular line and the reflected ray is θr."},{"sourceId":"fs-id1167066974416","filename":"CNX_HSPhysics_16_01_Reflect2.jpg","relativePath":"media/CNX_HSPhysics_16_01_Reflect2.jpg","alt":"A rough surface, such as the ground, is shown. Multiple rays are striking the uneven surface and are bouncing off the ground in different directions."},{"sourceId":"fs-id1167066778660","filename":"CNX_HSPhysics_16_01_FlatMirror.jpg","relativePath":"media/CNX_HSPhysics_16_01_FlatMirror.jpg","alt":"A flat mirror is placed perpendicular to our field of view. We see the side of the mirror. A bottle is placed to the left of the mirror at distance do to the mirror. Two rays originate from the bottle, strike the mirror, and reflect to an eye that is looking at the mirror. To the right of the mirror, a virtual image of the bottle is included as a backward extrapolation of the path of the rays from the eye to the mirror. The bottle to the right of the mirror is at distance di from the mirror."},{"sourceId":"fs-id1167063788875","filename":"CNX_HSPhysics_16_01_Maze.jpg","relativePath":"media/CNX_HSPhysics_16_01_Maze.jpg","alt":"This black-and-white still shot shows Charlie Chaplin and a thief in a maze of mirrors. Images of Chaplin and the thief appear in mirrors, within mirrors, within mirrors."},{"sourceId":"fs-id1167067250004","filename":"CNX_HSPhysics_16_01_Versailles.jpg","relativePath":"media/CNX_HSPhysics_16_01_Versailles.jpg","alt":"The Hall of Mirrors at Versailles features an al fresco and gilded domed ceiling; many large, hanging crystal chandeliers; exquisite painted panels on the walls; and mirrors—lots and lots of mirrors—to give an illusion of space. Tourists are pictured roaming the Hall."},{"sourceId":"fs-id1164562239727","filename":"CNX_HSPhysics_16_01_Maze.jpg","relativePath":"media/CNX_HSPhysics_16_01_Maze.jpg","alt":"A grayscale image of Charlie Chaplain in a house of mirrors is shown. There are infinite images of him, His image in the foreground has his hat tilted to the left."},{"sourceId":"fs-id1167061199473","filename":"CNX_HSPhysics_16_01_Curved.jpg","relativePath":"media/CNX_HSPhysics_16_01_Curved.jpg","alt":"There are two curved mirrors in this figure. In view (a), the front of a concave mirror is struck by rays of light that originate in front of the mirror. The rays reflect off the concave mirror and converge at varying angles to a point F in front of the mirror. The distance from F to the mirror is f. In view (b), the back of a convex mirror is struck by rays of light that diverge off the back of the mirror at varying angles. If one were to extrapolate the diverging rays backward, to the front of the mirror, the backward-extrapolated rays meet at point F; however, the distance from the back of the mirror to F is a negative f."},{"sourceId":"fs-id1167067295607","filename":"CNX_HSPhysics_16_01_Curved2.jpg","relativePath":"media/CNX_HSPhysics_16_01_Curved2.jpg","alt":"View (a) shows a concave mirror to the right with a lit candle to the left placed outside the focal point. It is a real image. View (b) shows a concave mirror to the right with a lit candle to the left placed inside the focal point. This image is virtual. View (c) shows a convex mirror to the right with a lit candle to the left. The image is virtual."},{"sourceId":"fs-id1167066793961","filename":"CNX_HSPhysics_16_01_Convex.jpg","relativePath":"media/CNX_HSPhysics_16_01_Convex.jpg","alt":"The image shows a woman taking a picture in front of a convex mirror."},{"sourceId":"fs-id1167067067990","filename":"CNX_HSPhysics_16_01_Schmidt.jpg","relativePath":"media/CNX_HSPhysics_16_01_Schmidt.jpg","alt":"There is an eye to the right of the diagram. The eye represents the focal plane. Moving from right to left, in front of the eye, there is a perforated primary mirror and a secondary mirror. The end of the telescope is to the left of the figure. Rays enter the end of the telescoped, hit the primary mirror, bounce backward to the secondary mirror, bounce through the hole (perforation) in the primary mirror, and travel to the eye."},{"sourceId":"fs-id1167067257728","filename":"CNX_HSPhysics_16_01_Concave.jpg","relativePath":"media/CNX_HSPhysics_16_01_Concave.jpg","alt":"This diagram shows a car headlight, also called a spotlight, which has a light bulb surrounded by a parabolic mirror. The mirror is bowl shaped, with the bulb sitting at the center of recessed side of the bowl. Arrows show that light rays from the bulb extend out in all directions and then bounce off of the mirror so that all of the light rays travel straight out from the headlight"},{"sourceId":"fs-id1167067139106","filename":"CNX_HSPhysics_16_01_Concave2.jpg","relativePath":"media/CNX_HSPhysics_16_01_Concave2.jpg","alt":"This photo depicts a long length of parabolic trough deflectors angled toward the sun."}],"tables":[{"sourceId":"Table_16_01","headers":["Type of Mirror","Object to Mirror Distance, d o","Image Characteristics"],"rows":[["Concave","\\({d}_{o} \\gt f\\)","Real and inverted"],["Concave","\\({d}_{o} \\lt f\\)","Virtual and erect"],["Convex","\\({d}_{o} \\lt \\text{or} \\gt f\\)","Virtual and erect"]]}]},{"uid":"hsphys.ch16.sec01.sub02","title":"The Application of the Curved Mirror Equations","summaryVi":"Định luật Phản xạ (θ_i = θ_r), Gương cầu lõm (f > 0), Gương cầu lồi (f < 0), Công thức gương 1/f = 1/d_o + 1/d_i và Độ phóng đại m = -d_i / d_o. Thuật ngữ trọng tâm trong mục này: focal length (Tiêu cự (f)).","paragraphs":["Curved mirrors and the images they create involve a fairly small number of variables: the mirror’s radius of curvature, R ; the focal length, f ; the distances of the object and image from the mirror, d o and d i , respectively; and the heights of the object and image, h o and h i , respectively. The signs of these values indicate whether the image is inverted, erect (upright), real, or virtual. We now look at the equations that relate these variables and apply them to everyday problems.","Figure 16.1 shows the meanings of most of the variables we will use for calculations involving curved mirrors.","The basic equation that describes both lenses and mirrors is the lens/mirror equation","This equation can be rearranged several ways. For example, it may be written to solve for focal length.","Magnification, m , is the ratio of the size of the image, h i , to the size of the object, h o . The value of m can be calculated in two ways.","This relationship can be written to solve for any of the variables involved. For example, the height of the image is given by","We saved the simplest equation for last. The radius of curvature of a curved mirror, R , is simply twice the focal length.","We can learn important information from the algebraic sign of the result of a calculation using the previous equations:","Now let’s apply these equations to solve some problems."],"figures":[{"sourceId":"fs-id1167066822035","filename":"CNX_HSPhysics_16_01_Ray2.jpg","relativePath":"media/CNX_HSPhysics_16_01_Ray2.jpg","alt":"This figure shows an old-fashioned key inside the focal point of a concave mirror. All the variables used for calculations involving curved mirrors depicted."}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch16.sec01.ex01","number":"16.1.1","title":"Calculating Focal Length","problem":"A person standing 6.0 m from a convex security mirror forms a virtual image that appears to be 1.0 m behind the mirror. What is the focal length of the mirror?","problemImages":[],"strategy":"The person is the object, so d o = 6.0 m. We know that, for this situation, d o is positive. The image is virtual, so the value for the image distance is negative, so d i = –1.0 m.\nNow, use the appropriate version of the lens/mirror equation to solve for focal length by substituting the known values.","solution":"\\(f = \\frac{{d}_{i}{d}_{o}}{{d}_{o} + {d}_{i}} = \\frac{( - 1.0)(6.0)}{6.0 + ( - 1.0)} = \\frac{- 6.0}{5.0} = - 1.2\\,\\text{m}\\)","solutionImages":[],"solutionTables":[],"discussion":"The negative result is expected for a convex mirror. This indicates the focal point is behind the mirror."},{"uid":"hsphys.ch16.sec01.ex02","number":"16.1.2","title":"Calculating Object Distance","problem":"Electric room heaters use a concave mirror to reflect infrared (IR) radiation from hot coils. Note that IR radiation follows the same law of reflection as visible light. Given that the mirror has a radius of curvature of 50.0 cm and produces an image of the coils 3.00 m in front of the mirror, where are the coils with respect to the mirror?","problemImages":[],"strategy":"We are told that the concave mirror projects a real image of the coils at an image distance d i = 3.00 m. The coils are the object, and we are asked to find their location—that is, to find the object distance d o . We are also given the radius of curvature of the mirror, so that its focal length is f = R /2 = 25.0 cm (a positive value, because the mirror is concave, or converging). We can use the lens/mirror equation to solve this problem.","solution":"Because d i and f are known, the lens/mirror equation can be used to find d o .\n\\(\\frac{1}{f} = \\frac{1}{{d}_{i}} + \\frac{1}{{d}_{o}}\\)\nRearranging to solve for d o , we have\n\\({d}_{o} = \\frac{{d}_{i}f}{{d}_{i} - f}.\\)\nEntering the known quantities gives us\n\\({d}_{o} = \\frac{(3.00\\, \\times \\,{10}^{2})(25.0)}{(3.00\\, \\times \\,{10}^{2}) - 25.0} = 27.3\\,\\text{cm}\\text{.}\\)","solutionImages":[],"solutionTables":[],"discussion":"Note that the object (the coil filament) is farther from the mirror than the mirror’s focal length. This is a case 1 image ( d o > f and f positive), consistent with the fact that a real image is formed. You get the most concentrated thermal energy directly in front of the mirror and 3.00 m away from it. In general, this is not desirable because it could cause burns. Usually, you want the rays to emerge parallel, and this is accomplished by having the filament at the focal point of the mirror.\nNote that the filament here is not much farther from the mirror than the focal length, and that the image produced is considerably farther away."}],"snapLabs":[{"uid":"hsphys.ch16.sec01.lab01","title":"Concave and Convex Mirrors","text":"Silver spoon and silver polish, or a new spoon made of any shiny metal\nInstructions\nProcedure\nChoose any small object with a top and a bottom, such as a short nail or tack, or a coin, such as a quarter. Observe the object’s reflection on the back of the spoon.\nObserve the reflection of the object on the front (bowl side) of the spoon when held away from the spoon at a distance of several inches.\nObserve the image while slowly moving the small object toward the bowl of the spoon. Continue until the object is all the way inside the bowl of the spoon.\nYou should see one point where the object disappears and then reappears. This is the focal point.","images":[]}],"tipsAndFeatures":[{"uid":"hsphys.ch16.sec01.feat01","type":"tip","title":"Tips for Success","text":"You can remember the difference between concave and convex by thinking, Concave means caved in .","images":[]}],"summaryPoints":["The angle of reflection equals the angle of incidence.","Plane mirrors and convex mirrors reflect virtual, erect images. Concave mirrors reflect light to form real, inverted images or virtual, erect images, depending on the location of the object.","Image distance, height, and other characteristics can be calculated using the lens/mirror equation and the magnification equation."],"glossary":[{"term":"angle of incidence","termVi":"Góc tới (θ_i)","ipa":"/ˈɪn.sɪ.dəns/","definition":"the angle, with respect to the normal, at which a ray meets a boundary between media or a reflective surface","definitionVi":"Góc tạo bởi tia tới và đường PHÁP TUYẾN (vuông góc mặt gương/mặt phân cách).","memoryTipVi":"⚠️ Luôn đo góc so với đường PHÁP TUYẾN (Normal), KHÔNG đo so với mặt gương!"},{"term":"angle of reflection","termVi":"Góc phản xạ (θ_r)","ipa":"/rɪˈflek.ʃən/","definition":"the angle, with respect to the normal, at which a ray leaves a reflective surface","definitionVi":"Góc tạo bởi tia phản xạ và đường pháp tuyến.","memoryTipVi":"Luôn bằng góc tới: θ_i = θ_r."},{"term":"central axis","termVi":"Trục chính (quang trục)","ipa":"/ˈsen.trəl ˈæk.sɪs/","definition":"a line perpendicular to the center of a lens or mirror extending in both directions","definitionVi":"Đường thẳng đi qua quang tâm/đỉnh gương và tiêu điểm chính.","memoryTipVi":"Tia đi song song trục chính sẽ hội tụ qua tiêu điểm F."},{"term":"concave mirror","termVi":"Gương cầu lõm (Gương hội tụ)","ipa":"/ˌkɒnˈkeɪv ˈmɪr.ər/","definition":"a mirror with a reflective side that is curved inward","definitionVi":"Gương có mặt phản xạ lõm vào trong (như lòng thìa) — hội tụ tia sáng (f > 0).","memoryTipVi":"Con-CAVE = lõm như cái hang (cave)."},{"term":"convex mirror","termVi":"Gương cầu lồi (Gương phân kỳ)","ipa":"/ˌkɒnˈveks ˈmɪr.ər/","definition":"a mirror with a reflective side that is curved outward","definitionVi":"Gương có mặt phản xạ lồi ra ngoài — luôn cho ảnh ảo nhỏ hơn vật, góc nhìn rộng (f < 0, dùng làm gương chiếu hậu).","memoryTipVi":"Gương cầu lồi luôn có f < 0 và luôn cho ảnh ảo!"},{"term":"focal length","termVi":"Tiêu cự (f)","ipa":"/ˈfəʊ.kəl leŋθ/","definition":"the distance from the focal point to the mirror","definitionVi":"Khoảng cách từ đỉnh gương / quang tâm thấu kính đến tiêu điểm chính (với gương cầu: f = R/2).","memoryTipVi":"Công thức gương & thấu kính: 1/f = 1/d_o + 1/d_i."},{"term":"focal point","termVi":"Tiêu điểm chính (F)","ipa":"/ˈfəʊ.kəl pɔɪnt/","definition":"the point at which rays converge or appear to converge","definitionVi":"Điểm mà chùm tia song song trục chính hội tụ (hoặc đường kéo dài cắt nhau).","memoryTipVi":"Ký hiệu F."},{"term":"law of reflection","termVi":"Định luật Phản xạ ánh sáng","ipa":"/lɔː əv rɪˈflek.ʃən/","definition":"the law that indicates the angle of reflection equals the angle of incidence","definitionVi":"Tia phản xạ nằm trong mặt phẳng tới và góc phản xạ bằng góc tới (θ_r = θ_i).","memoryTipVi":"Đúng cho mọi loại gương (phẳng, cầu lồi, cầu lõm)."},{"term":"law of refraction","termVi":"Định luật Khúc xạ ánh sáng (Định luật Snell)","ipa":"/rɪˈfræk.ʃən/","definition":"the law that describes the relationship between refractive indices of materials on both sides of a boundary and the change in the path of light crossing the boundary, as given by the equation n 1 sin \\({\\theta}_{1}\\)\n= n 2 sin \\({\\theta}_{2}\\)","definitionVi":"n₁ sinθ₁ = n₂ sinθ₂.","memoryTipVi":"Khi đi từ môi trường chiết suất nhỏ sang lớn (không khí → nước), tia sáng bẻ GẦN pháp tuyến hơn."},{"term":"ray","termVi":"Tia sáng","ipa":"/reɪ/","definition":"light traveling in a straight line","definitionVi":"Đường thẳng có mũi tên biểu diễn hướng truyền của ánh sáng.","memoryTipVi":"Quang học hình học (Geometric Optics) dùng mô hình tia sáng."},{"term":"real image","termVi":"Ảnh thật","ipa":"/rɪəl ˈɪm.ɪdʒ/","definition":"an optical image formed when light rays converge and pass through the image, producing an image that can be projected onto a screen","definitionVi":"Ảnh tạo bởi các tia sáng thực sự cắt nhau — HỨNG ĐƯỢC trên màn chắn và luôn ngược chiều vật (d_i > 0).","memoryTipVi":"Ảnh thật luôn ngược chiều (inverted)."},{"term":"virtual image","termVi":"Ảnh ảo","ipa":"/ˈvɜː.tʃu.əl ˈɪm.ɪdʒ/","definition":"the point from which light rays appear to diverge without actually doing so","definitionVi":"Ảnh tạo bởi đường kéo dài của tia sáng — KHÔNG hứng được trên màn chắn và luôn cùng chiều vật (d_i < 0).","memoryTipVi":"Ảnh trong gương phẳng là ảnh ảo!"}],"assessments":[{"uid":"hsphys.ch16.sec01.q001","sourceId":"fs-id1167062385114","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"How does the object distance, d o , compare with the focal length, f, for a concave mirror that produces an image that is real and inverted?","images":[],"choices":[{"label":"a","text":"d o > f, where d o and f are object distance and focal length, respectively."},{"label":"b","text":"d o < f, where d o and f are object distance and focal length, respectively."},{"label":"c","text":"d o = f, where do and f are object distance and focal length, respectively."},{"label":"d","text":"d o = 0, where do is the object distance."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec01.q005","sourceId":"fs-id1167062379507","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"What is the focal length of a makeup mirror that produces a magnification of 1.50 when a person’s face is 12.0 cm away? Construct a ray diagram using paper, a pencil and a ruler to confirm your calculation.","images":[],"choices":[{"label":"a","text":"–36.0 cm"},{"label":"b","text":"–7.20 cm"},{"label":"c","text":"7.20 cm"},{"label":"d","text":"36.0 cm"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec01.q006","sourceId":"fs-id1167065736270","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Part A. Can you see a virtual image? Part B. Can you photograph one? Explain your answers.","images":[],"choices":[{"label":"a","text":"A. yes; B. No, an image from a flat mirror cannot be photographed."},{"label":"b","text":"A. no; B. Yes, an image from a flat mirror can be photographed."},{"label":"c","text":"A. yes; B. Yes, an image from a flat mirror can be photographed."},{"label":"d","text":"A. no; B. No, an image from a flat mirror cannot be photographed."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec01.q007","sourceId":"eip-id1166851181863","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"State the law of reflection.","images":[],"choices":[{"label":"a","text":"\\({ϑ}_{r} = {ϑ}_{i}\\), where \\({ϑ}_{r}\\) is the angle of reflection and \\({ϑ}_{i}\\) is the angle of incidence."},{"label":"b","text":"\\({ϑ}_{r} \\gt {ϑ}_{i}\\), where \\({ϑ}_{r}\\) is the angle of reflection and \\({ϑ}_{i}\\) is the angle of incidence."},{"label":"c","text":"\\({ϑ}_{r} \\lt {ϑ}_{i}\\), where \\({ϑ}_{r}\\) is the angle of reflection and \\({ϑ}_{i}\\) is the angle of incidence."},{"label":"d","text":"\\({ϑ}_{r} = 0\\), where \\({ϑ}_{r}\\) is the angle of reflection."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec01.q010","sourceId":"fs-id1167062379507","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"What is the focal length of a makeup mirror that produces a magnification of 1.50 when a person’s face is 12.0 cm away? Construct a ray diagram using paper, a pencil and a ruler to confirm your calculation.","images":[],"choices":[{"label":"a","text":"–36.0 cm"},{"label":"b","text":"–7.20 cm"},{"label":"c","text":"7.20 cm"},{"label":"d","text":"36.0 cm"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec01.q011","sourceId":"fs-id1167064872659","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Some telephoto cameras use a mirror rather than a lens. What radius of curvature is needed for a concave mirror to replace a 0.800 -m focal-length telephoto lens?","images":[],"choices":[{"label":"a","text":"0.400 m"},{"label":"b","text":"1.60 m"},{"label":"c","text":"4.00 m"},{"label":"d","text":"16.0 m"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec01.q012","sourceId":"fs-id1167065946680","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"What is the focal length of a makeup mirror that produces a magnification of 2.00 when a person’s face is 8.00 cm away?","images":[],"choices":[{"label":"a","text":"–16 cm"},{"label":"b","text":"–5.3 cm"},{"label":"c","text":"5.3 cm"},{"label":"d","text":"16 cm"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec01.q013","sourceId":"fs-id1167065787755","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"In geometric optics, a straight line emerging from a point is called a (an) ________.","images":[],"choices":[{"label":"a","text":"ray"},{"label":"b","text":"focal point"},{"label":"c","text":"image"},{"label":"d","text":"object distance"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec01.q014","sourceId":"fs-id1167064645926","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"An image of a 2.0 -cm object reflected from a mirror is 5.0 cm tall. What is the magnification of the mirror?","images":[],"choices":[{"label":"a","text":"0.4"},{"label":"b","text":"2.5"},{"label":"c","text":"3"},{"label":"d","text":"10"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec01.q015","sourceId":"eip-id1166848716442","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Can a virtual image be projected onto a screen with additional lenses or mirrors? Explain your answer.","images":[],"choices":[{"label":"a","text":"Yes, the rays actually meet behind the lens or mirror."},{"label":"b","text":"No, the image is formed by rays that converge to a point in front of the mirror or lens."},{"label":"c","text":"Yes, any image that can be seen can be manipulated so that it can be projected onto a screen."},{"label":"d","text":"No, the image can only be perceived as being behind the lens or mirror."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec01.q016","sourceId":"fs-id1167065949667","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Distinguish between reflection and refraction in terms of how a light ray changes when it meets the interface between two media.","images":[],"choices":[{"label":"a","text":"Reflected light penetrates the surface whereas refracted light is bent as it travels from one medium to the other."},{"label":"b","text":"Reflected light penetrates the surface whereas refracted light travels along a curved path."},{"label":"c","text":"Reflected light bounces from the surface whereas refracted light travels along a curved path."},{"label":"d","text":"Reflected light bounces from the surface whereas refracted light is bent as it travels from one medium to the other."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec01.q018","sourceId":"fs-id1167065943512","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"A concave mirror has a focal length of 5.00 cm. What is the image distance of an object placed 7.00 cm from the center of the mirror?","images":[],"choices":[{"label":"a","text":"-17.5 cm"},{"label":"b","text":"-2.92 cm"},{"label":"c","text":"2.92 cm"},{"label":"d","text":"17.5 cm"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec01.q019","sourceId":"fs-id1167062461376","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"An 8.0 -cm tall object is placed 6.0 cm from a concave mirror with a magnification of 2.0. What are the image height and the image distance?","images":[],"choices":[{"label":"a","text":"h i =  16 cm, d i =  12 cm"},{"label":"b","text":"h i =  16 cm, d i = 12 cm"},{"label":"c","text":"h i = 16 cm, d i =  12 cm"},{"label":"d","text":"h i = 16 cm, d i = 12 cm"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec01.q020","sourceId":"fs-id1167065020746","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"The diagram shows a lightbulb between two mirrors. One mirror produces a beam of light with parallel rays; the other keeps light from escaping without being put into the beam.\nWhere is the light source in relation to the focal point or radius of\ncurvature of each mirror? Explain your answer.","images":[{"sourceId":"eip-idm520812096","filename":"CNX_HSPhysics_16_01_Curved3.jpg","relativePath":"media/CNX_HSPhysics_16_01_Curved3.jpg","alt":"A diagram illustrating a light bulb positioned between two concave mirrors, demonstrating how light rays are reflected to create a parallel beam, often used in headlights or flashlights."}],"choices":[{"label":"a","text":"The bulb is at the center of curvature of the small mirror and at the focal point of the large mirror."},{"label":"b","text":"The bulb is at the focal point of the small mirror and at the focal point of the large mirror."},{"label":"c","text":"The bulb is at the center of curvature of the small mirror and at the center of curvature of the large mirror."},{"label":"d","text":"The bulb is at the focal point of the small mirror and at the center of curvature of the large mirror."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":4,"subsectionCount":2,"workedExampleCount":2,"snapLabCount":1,"glossaryCount":12,"assessmentCount":14}},{"uid":"hsphys.ch16.sec02","moduleId":"m54365","number":"16.2","slug":"refraction","title":"Refraction","isIntroduction":false,"learningObjectives":["Explain refraction at media boundaries, predict the path of light after passing through a boundary (Snell’s law), describe the index of refraction of materials, explain total internal reflection, and describe applications of refraction and total internal reflection","Perform calculations based on the law of refraction, Snell’s law, and the conditions for total internal reflection"],"bilingualGuide":{"notebookSummaryVi":"Định luật Khúc xạ Snell (n₁ sinθ₁ = n₂ sinθ₂), Chiết suất n = c/v, Phản xạ toàn phần (sinθ_c = n₂/n₁) và Tán sắc ánh sáng.","wordProblemCues":[{"phraseEn":"Snell’s law / critical angle","meaningVi":"Định luật Snell / Góc giới hạn","mathNotation":"n₁sinθ₁ = n₂sinθ₂"}],"commonTrapsVi":["Mọi góc tới và góc khúc xạ đều đo so với đường PHÁP TUYẾN (vuông góc mặt phân cách), không đo với mặt nước!"]},"keyEquations":[{"name":"index of Refraction","formula":"\\(n = \\frac{c}{v}\\)"},{"name":"Snell’s law","formula":"\\({n}_{1}sin{\\theta}_{1} = {n}_{2}sin{\\theta}_{2}\\text{or}\\frac{{n}_{1}}{{n}_{2}} = \\frac{\\text{sin}{\\theta}_{2}}{\\text{sin}{\\theta}_{1}}\\)"},{"name":">Snell’s law in terms of speed","formula":"\\(\\frac{sin{\\theta}_{1}}{sin{\\theta}_{2}} = \\frac{{v}_{1}}{{v}_{2}}\\)"},{"name":"critical angle","formula":"\\({\\theta}_{c} = {sin}^{-1}(\\frac{{n}_{2}}{{n}_{1}}\\text{), for}{n}_{1} \\gt {n}_{2}\\)"}],"subsections":[{"uid":"hsphys.ch16.sec02.sub01","title":"The Law of Refraction","summaryVi":"Định luật Khúc xạ Snell (n₁ sinθ₁ = n₂ sinθ₂), Chiết suất n = c/v, Phản xạ toàn phần (sinθ_c = n₂/n₁) và Tán sắc ánh sáng. Thuật ngữ trọng tâm trong mục này: angle of refraction (Góc khúc xạ (θ₂)), critical angle (Góc giới hạn phản xạ toàn phần (θ_c)), dispersion (Sự tán sắc ánh sáng), incident ray (Tia tới).","paragraphs":["You may have noticed some odd optical phenomena when looking into a fish tank. For example, you may see the same fish appear to be in two different places (Figure 16.2). This is because light coming to you from the fish changes direction when it leaves the tank and, in this case, light rays traveling along two different paths both reach our eyes. The changing of a light ray’s direction (loosely called bending ) when it passes a boundary between materials of different composition, or between layers in single material where there are changes in temperature and density, is called refraction . Refraction is responsible for a tremendous range of optical phenomena, from the action of lenses to voice transmission through optical fibers.","Why does light change direction when passing from one material (medium) to another? It is because light changes speed when going from one material to another. This behavior is typical of all waves and is especially easy to apply to light because light waves have very small wavelengths, and so they can be treated as rays. Before we study the law of refraction, it is useful to discuss the speed of light and how it varies between different media.","The speed of light is now known to great precision. In fact, the speed of light in a vacuum, c , is so important, and is so precisely known, that it is accepted as one of the basic physical quantities, and has the fixed value","where the approximate value of 3.00 \\(\\times\\) 10 8 m/s is used whenever three-digit precision is sufficient. The speed of light through matter is less than it is in a vacuum, because light interacts with atoms in a material. The speed of light depends strongly on the type of material, given that its interaction with different atoms, crystal lattices, and other substructures varies. We define the index of refraction , n , of a material to be","where v is the observed speed of light in the material. Because the speed of light is always less than c in matter and equals c only in a vacuum, the index of refraction (plural: indices of refraction) is always greater than or equal to one.","the table below lists the indices of refraction in various common materials.","Figure 16.2 provides an analogy for and a description of how a ray of light changes direction when it passes from one medium to another. As in the previous section, the angles are measured relative to a perpendicular to the surface at the point where the light ray crosses it. The change in direction of the light ray depends on how the speed of light changes. The change in the speed of light is related to the indices of refraction of the media involved. In the situations shown in Figure 16.2, medium 2 has a greater index of refraction than medium 1. This difference in index of refraction means that the speed of light is less in medium 2 than in medium 1. Note that, in Figure 16.2(a), the path of the ray moves closer to the perpendicular when the ray slows down. Conversely, in Figure 16.2(b), the path of the ray moves away from the perpendicular when the ray speeds up. The path is exactly reversible. In both cases, you can imagine what happens by thinking about pushing a lawn mower from a footpath onto grass, and vice versa. Going from the footpath to grass, the right front wheel is slowed and pulled to the side as shown. This is the same change in direction for light when it goes from a fast medium to a slow one. When going from the grass to the footpath, the left front wheel moves faster than the others, and the mower changes direction as shown. This, too, is the same change in direction as light going from slow to fast.","The Bending Light simulation allows you to show light refracting as it crosses the boundaries between various media (download animation first to view). It also shows the reflected ray. You can move the protractor to the point where the light meets the boundary and measure the angle of incidence, the angle of refraction , and the angle of reflection. You can also insert a prism into the beam to view the spreading, or dispersion , of white light into colors, as discussed later in this section. Use the ray option at the upper left.","The amount that a light ray changes direction depends both on the incident angle and the amount that the speed changes. For a ray at a given incident angle, a large change in speed causes a large change in direction, and thus a large change in the angle of refraction. The exact mathematical relationship is the law of refraction, or Snell’s law , which is stated in equation form as","In terms of speeds, Snell’s law becomes","Here, n 1 and n 2 are the indices of refraction for media 1 and 2, respectively, and θ 1 and θ 2 are the angles between the rays and the perpendicular in the respective media 1 and 2, as shown in Figure 16.2. The incoming ray is called the incident ray and the outgoing ray is called the refracted ray . The associated angles are called the angle of incidence and the angle of refraction . Later, we apply Snell’s law to some practical situations.","Dispersion is defined as the spreading of white light into the wavelengths of which it is composed. This happens because the index of refraction varies slightly with wavelength. Figure 16.2 shows how a prism disperses white light into the colors of the rainbow.","Rainbows are produced by a combination of refraction and reflection. You may have noticed that you see a rainbow only when you turn your back to the Sun. Light enters a drop of water and is reflected from the back of the drop, as shown in Figure 16.2. The light is refracted both as it enters and as it leaves the drop. Because the index of refraction of water varies with wavelength, the light is dispersed and a rainbow is observed.","A good-quality mirror reflects more than 90 percent of the light that falls on it; the mirror absorbs the rest. But, it would be useful to have a mirror that reflects all the light that falls on it. Interestingly, we can produce total reflection using an aspect of refraction. Consider what happens when a ray of light strikes the surface between two materials, such as is shown in Figure 16.2(a). Part of the light crosses the boundary and is refracted; the rest is reflected. If, as shown in the figure, the index of refraction for the second medium is less than the first, the ray bends away from the perpendicular. Because n 1 > n 2 , the angle of refraction is greater than the angle of incidence—that is, \\({\\theta}_{\\text{2}}\\) > \\({\\theta}_{\\text{1}}\\) . Now, imagine what happens as the incident angle is increased. This causes \\({\\theta}_{\\text{2}}\\) to increase as well. The largest the angle of refraction, \\({\\theta}_{\\text{2}}\\), can be is 90°, as shown in Figure 16.2(b). The critical angle , \\({\\theta}_{\\text{c}}\\), for a combination of two materials is defined to be the incident angle, \\({\\theta}_{\\text{1}}\\), which produces an angle of refraction of 90°. That is, \\({\\theta}_{\\text{c}}\\) is the incident angle for which \\({\\theta}_{\\text{2}}\\) = 90°. If the incident angle, \\({\\theta}_{\\text{1}}\\), is greater than the critical angle, as shown in Figure 16.2(c), then all the light is reflected back into medium 1, a condition called total internal reflection .","Recall that Snell’s law states the relationship between angles and indices of refraction. It is given by","When the incident angle equals the critical angle ( \\({\\theta}_{\\text{1}}\\)\n= \\({\\theta}_{\\text{c}}\\)\n), the angle of refraction is 90° ( \\({\\theta}_{\\text{2}}\\)\n= 90°). Noting that sin 90° = 1, Snell’s law in this case becomes","The critical angle, \\({\\theta}_{\\text{c}}\\), for a given combination of materials is thus","for n 1 > n 2 .","Total internal reflection occurs for any incident angle greater than the critical angle, \\({\\theta}_{\\text{c}}\\), and it can only occur when the second medium has an index of refraction less than the first. Note that the previous equation is written for a light ray that travels in medium 1 and reflects from medium 2, as shown in Figure 16.2.","There are several important applications of total internal reflection. Total internal reflection, coupled with a large index of refraction, explains why diamonds sparkle more than other materials. The critical angle for a diamond-to-air surface is only 24.4°; so, when light enters a diamond, it has trouble getting back out (Figure 16.2). Although light freely enters the diamond at different angles, it can exit only if it makes an angle less than 24.4° with the normal to a given surface. Facets on diamonds are specifically intended to make this unlikely, so that the light can exit only in certain places. Diamonds with very few impurities are very clear, so the light makes many internal reflections and is concentrated at the few places it can exit—hence the sparkle.","A light ray that strikes an object that consists of two mutually perpendicular reflecting surfaces is reflected back exactly parallel to the direction from which it came. This parallel reflection is true whenever the reflecting surfaces are perpendicular, and it is independent of the angle of incidence. Such an object is called a corner reflector because the light bounces from its inside corner. Many inexpensive reflector buttons on bicycles, cars, and warning signs have corner reflectors designed to return light in the direction from which it originates. Corner reflectors are perfectly efficient when the conditions for total internal reflection are satisfied. With common materials, it is easy to obtain a critical angle that is less than 45°. One use of these perfect mirrors is in binoculars, as shown in Figure 16.2. Another application is for periscopes used in submarines.","Fiber optics are one common application of total internal reflection. In communications, fiber optics are used to transmit telephone, internet, and cable TV signals, and they use the transmission of light down fibers of plastic or glass. Because the fibers are thin, light entering one is likely to strike the inside surface at an angle greater than the critical angle and, thus, be totally reflected (Figure 16.2). The index of refraction outside the fiber must be smaller than inside, a condition that is satisfied easily by coating the outside of the fiber with a material that has an appropriate refractive index. In fact, most fibers have a varying refractive index to allow more light to be guided along the fiber through total internal reflection. Rays are reflected around corners as shown in the figure, making the fibers into tiny light pipes ."],"figures":[{"sourceId":"fs-id1167064791995","filename":"CNX_HSPhysics_16_02_Fish.jpg","relativePath":"media/CNX_HSPhysics_16_02_Fish.jpg","alt":"A man is looking at the corner of a fish tank. Although the fish is directly in his line of sight, he sees the fish to the right and left of the corner of the fish tank."},{"sourceId":"fs-id1167065951196","filename":"CNX_HSPhysics_16_02_Lawnmower.jpg","relativePath":"media/CNX_HSPhysics_16_02_Lawnmower.jpg","alt":"In view (a), a lawnmower is on a sidewalk and is approaching a strip of grass, which is perpendicular to the sidewalk, at angle θ1. As the right front wheel of the lawnmower hits the grass, the path of the angle, θ1, moves closer to the perpendicular. In view (b), a lawnmower is on the grass and is approaching the sidewalk, which is perpendicular to the grass, at angle θ2. As the left front wheel of the lawnmower hits the sidewalk, the path of the angle, θ2, moves farther from the perpendicular."},{"sourceId":"fs-id1167065859579","filename":"CNX_HSPhysics_16_02_Prism.jpg","relativePath":"media/CNX_HSPhysics_16_02_Prism.jpg","alt":"In view (a), a ray of pure light (denoted by an arrow) hits the edge of a glass prism at an angle. As demonstrated by the arrow, this light is refracted as it enters the prism and as it exits the prism. In view (b), white light (also denoted by an arrow) hits the edge of a glass prism at an angle. In this case the ray of light disperses, as shown by two arrows originating where the white light enters the prism. When the rays pass through the prism, the angle widens and a rainbow of light is seen exiting the prism."},{"sourceId":"fs-id1167065877584","filename":"CNX_HSPhysics_16_02_Rainbow.jpg","relativePath":"media/CNX_HSPhysics_16_02_Rainbow.jpg","alt":"A water droplet is depicted in this figure. A ray of sunlight, denoted by an arrow, hits drop of water and disperses at its point of entry, denoted by the arrow splitting in two. These two rays are then reflected off the back of the droplet at two different angles and are dispersed again as they leave the droplet, creating a rainbow."},{"sourceId":"fs-id1167065735762","filename":"CNX_HSPhysics_16_02_TotalInt.jpg","relativePath":"media/CNX_HSPhysics_16_02_TotalInt.jpg","alt":"Views (a) through (c) depict how light behaves when light strikes a boundary and is reflected and refracted."},{"sourceId":"fs-id1167066044617","filename":"CNX_HSPhysics_16_02_Diamond.jpg","relativePath":"media/CNX_HSPhysics_16_02_Diamond.jpg","alt":"A sketch of a diamond shows a ray of light entering the diamond and bouncing of various facets of the diamond at an angle less than the critical angle."},{"sourceId":"fs-id1167066112774","filename":"CNX_HSPhysics_16_02_Binoculars.jpg","relativePath":"media/CNX_HSPhysics_16_02_Binoculars.jpg","alt":"A pair of binoculars is shown. The right side is a cutout view of the internal workings of the binoculars. A light ray (depicted by an arrow) enters the binoculars, reflects off two prisms (corner reflectors) to transmit the image, which exits the eyepiece."},{"sourceId":"fs-id1167065850467","filename":"CNX_HSPhysics_16_02_Fiber.jpg","relativePath":"media/CNX_HSPhysics_16_02_Fiber.jpg","alt":"View (a) shows a cross-section of a fiber optic cable that consists of a core (n1) and thin cladding (n2). A light ray (depicted by an arrow) enters the cable/fiber and reflects off various surfaces. View (b) shows a cross-section of a bent thin fiber and a light ray that reflects off the sides and around corners."}],"tables":[{"sourceId":"Table_16_02_Refractive_Indices","headers":["Medium","n"],"rows":[["Gases at 0 °C and 1 atm",""],["Air","1.000293"],["Carbon dioxide","1.00045"],["Hydrogen","1.000139"],["Oxygen","1.000271"],["Liquids at 20 °C",""],["Benzene","1.501"],["Carbon disulfide","1.628"],["Carbon tetrachloride","1.461"],["Ethanol","1.361"],["Glycerin","1.473"],["Water, fresh","1.333"],["Solids at 20 °C",""],["Diamond","2.419"],["Fluorite","1.434"],["Glass, crown","1.52"],["Glass, flint","1.66"],["Ice at 0 °C","1.309"],["Plexiglas","1.51"],["Polystyrene","1.49"],["Quartz, crystalline","1.544"],["Quartz, fused","1.458"],["Sodium chloride","1.544"],["Zircon","1.923"]]}]},{"uid":"hsphys.ch16.sec02.sub02","title":"Calculations with the Law of Refraction","summaryVi":"Định luật Khúc xạ Snell (n₁ sinθ₁ = n₂ sinθ₂), Chiết suất n = c/v, Phản xạ toàn phần (sinθ_c = n₂/n₁) và Tán sắc ánh sáng. Thuật ngữ trọng tâm trong mục này: critical angle (Góc giới hạn phản xạ toàn phần (θ_c)), Snell’s law (Định luật Snell).","paragraphs":["The calculation problems that follow require application of the following equations:","and","These are the equations for refractive index, the mathematical statement of the law of refraction (Snell’s law), and the equation for the critical angle."],"figures":[],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch16.sec02.ex01","number":"16.2.1","title":"Calculating Index of Refraction from Speed","problem":"Calculate the index of refraction for a solid medium in which the speed of light is 2.012 \\(\\times\\) 10 8 m/s, and identify the most likely substance, based on the previous table of indicies of refraction.","problemImages":[],"strategy":"We know the speed of light, c , is 3.00 \\(\\times\\) 10 8 m/s, and we are given v . We can simply plug these values into the equation for index of refraction, n .","solution":"\\(n = \\frac{c}{v} = \\frac{3.00\\, \\times \\,{10}^{8}\\text{m/s}}{2.012\\, \\times \\,{10}^{8}\\text{m/s}} = 1.49\\)\nThis value matches that of polystyrene exactly, according to the table of indices of refraction (the table below).","solutionImages":[],"solutionTables":[],"discussion":"The three-digit approximation for c is used, which in this case is all that is needed. Many values in the table are only given to three significant figures. Note that the units for speed cancel to yield a dimensionless answer, which is correct."},{"uid":"hsphys.ch16.sec02.ex02","number":"16.2.2","title":"Calculating Index of Refraction from Angles","problem":"Suppose you have an unknown, clear solid substance immersed in water and you wish to identify it by finding its index of refraction. You arrange to have a beam of light enter it at an angle of 45.00°, and you observe the angle of refraction to be 40.30°. What are the index of refraction of the substance and its likely identity?","problemImages":[],"strategy":"We must use the mathematical expression for the law of refraction to solve this problem because we are given angle data, not speed data.\n\\(\\frac{{n}_{1}}{{n}_{2}} = \\frac{\\text{sin}{\\theta}_{2}}{\\text{sin}{\\theta}_{1}}\\)\nThe subscripts 1 and 2 refer to values for water and the unknown, respectively, where 1 represents the medium from which the light is coming and 2 is the new medium it is entering. We are given the angle values, and the table of indicies of refraction gives us n for water as 1.333. All we have to do before solving the problem is rearrange the equation\n\\({n}_{2} = \\frac{{n}_{1}\\text{sin}{\\theta}_{1}}{\\text{sin}{\\theta}_{2}}.\\)","solution":"\\({n}_{2} = \\frac{(1.333)(0.7071)}{0.6468} = 1.457\\)\nThe best match from the table below is fused quartz, with n = 1.458.","solutionImages":[],"solutionTables":[],"discussion":"Note the relative sizes of the variables involved. For example, a larger angle has a larger sine value. This checks out for the two angles involved. Note that the smaller value of \\({\\theta}_{\\text{2}}\\) compared with \\({\\theta}_{\\text{1}}\\) indicates the ray has bent toward normal. This result is to be expected if the unknown substance has a greater n value than that of water. The result shows that this is the case."},{"uid":"hsphys.ch16.sec02.ex03","number":"16.2.3","title":"Calculating Critical Angle","problem":"Verify that the critical angle for light going from water to air is 48.6°. (See the table below, the table of indices of refraction.)","problemImages":[],"strategy":"First, choose the equation for critical angle\n\\({\\theta}_{c} = {sin}^{- 1}(\\frac{{n}_{2}}{{n}_{1}})\\text{, for}{n}_{1} \\gt {n}_{2}.\\)\nThen, look up the n values for water, n 1 , and air, n 2 . Find the value of\n\\(\\frac{{n}_{2}}{{n}_{1}}\\) . Last, find the angle that has a sine equal to this value and it compare with the given angle of 48.6°.","solution":"For water, n 1 = 1.333; for air, n 2 = 1.0003. So,\n\\(\\begin{aligned} \\frac{{n}_{2}}{{n}_{1}} = \\frac{1.0003}{1.333} = 0.7504 \\\\ {sin}^{- 1}(0.7504) = 48.63°. \\end{aligned}\\)","solutionImages":[],"solutionTables":[],"discussion":"Remember, when we try to find a critical angle, we look for the angle at which light can no longer escape past a medium boundary by refraction. It is logical, then, to think of subscript 1 as referring to the medium the light is trying to leave, and subscript 2 as where it is trying (unsuccessfully) to go. So water is 1 and air is 2."}],"snapLabs":[{"uid":"hsphys.ch16.sec02.lab01","title":"Bent Pencil","text":"A classic observation of refraction occurs when a pencil is placed in a glass filled halfway with water. Do this and observe the shape of the pencil when you look at it sideways through air, glass, and water.\nA full-length pencil\nA glass half full of water\nInstructions\nProcedure\nPlace the pencil in the glass of water.\nObserve the pencil from the side.\nExplain your observations.","images":[]}],"tipsAndFeatures":[{"uid":"hsphys.ch16.sec02.feat01","type":"physics-in-action","title":"Medicine: Endoscopes","text":"A medical device called an endoscope is shown in Figure 16.2.\nEndoscopes, such as the one drawn here, send light down a flexible fiber optic tube, which sends images back to a doctor in charge of performing a medical procedure.\nThe word endoscope means looking inside . Doctors use endoscopes to look inside hollow organs in the human body and inside body cavities. These devices are used to diagnose internal physical problems. Images may be transmitted to an eyepiece or sent to a video screen. Another channel is sometimes included to allow the use of small surgical instruments. Such surgical procedures include collecting biopsies for later testing, and removing polyps and other growths.","images":[{"sourceId":"fs-id1167064720471","filename":"CNX_HSPhysics_16_02_Endoscope.jpg","relativePath":"media/CNX_HSPhysics_16_02_Endoscope.jpg","alt":"A sketch of an endoscope shows the eyepiece attached to an optic tube."}]}],"summaryPoints":["The index of refraction for a material is given by the speed of light in a vacuum divided by the speed of light in that material.","Snell’s law states the relationship between indices of refraction, the incident angle, and the angle of refraction.","The critical angle, \\({\\theta}_{\\text{c}}\\), determines whether total internal refraction can take place, and can be calculated according to \\({\\theta}_{c} = si{n}^{- 1}(\\frac{{n}_{2}}{{n}_{1}})\\) ."],"glossary":[{"term":"angle of refraction","termVi":"Góc khúc xạ (θ₂)","ipa":"/rɪˈfræk.ʃən/","definition":"the angle between the normal and the refracted ray","definitionVi":"Góc tạo bởi tia khúc xạ và đường pháp tuyến.","memoryTipVi":"Đo so với pháp tuyến!"},{"term":"critical angle","termVi":"Góc giới hạn phản xạ toàn phần (θ_c)","ipa":"/ˈkrɪt.ɪ.kəl ˈæŋ.ɡəl/","definition":"an incident angle that produces an angle of refraction of 90°","definitionVi":"Góc tới ứng với góc khúc xạ bằng 90°: sinθ_c = n₂ / n₁ (với n₁ > n₂).","memoryTipVi":"Nếu góc tới θ₁ > θ_c thì xảy ra phản xạ toàn phần!"},{"term":"dispersion","termVi":"Sự tán sắc ánh sáng","ipa":"/dɪˈspɜː.ʃən/","definition":"separation of white light into its component wavelengths","definitionVi":"Sự phân tách ánh sáng trắng thành dải màu cầu vồng qua lăng kính (do chiết suất n phụ thuộc bước sóng λ).","memoryTipVi":"Ánh sáng TÍM bị bẻ lệch nhiều nhất, ĐỎ lệch ít nhất!"},{"term":"incident ray","termVi":"Tia tới","ipa":"/ˈɪn.sɪ.dənt reɪ/","definition":"the incoming ray toward a medium boundary or a reflective surface","definitionVi":"Tia sáng chiếu tới mặt phân cách hai môi trường.","memoryTipVi":"Tia tới → Tia khúc xạ / phản xạ."},{"term":"index of refraction","termVi":"Chiết suất tuyệt đối (n = c/v)","ipa":"/ˈɪn.deks/","definition":"the speed of light in a vacuum divided by the speed of light in a given material","definitionVi":"Tỉ số giữa tốc độ ánh sáng trong chân không và tốc độ ánh sáng trong môi trường đó (luôn ≥ 1).","memoryTipVi":"Không khí n ≈ 1.00; Nước n ≈ 1.33; Thủy tinh n ≈ 1.5; Kim cương n ≈ 2.42."},{"term":"refracted ray","termVi":"Tia khúc xạ","ipa":"/rɪˈfræk.tɪd reɪ/","definition":"the light ray after it has been refracted","definitionVi":"Tia sáng bị bẻ gãy hướng sau khi đi sang môi trường thứ hai.","memoryTipVi":"Gây ảo giác chiếc đũa bị gãy trong cốc nước."},{"term":"Snell’s law","termVi":"Định luật Snell","ipa":"/snelz lɔː/","definition":"the law of refraction expressed mathematically as \\({n}_{1}sin{\\theta}_{1} = {n}_{2}sin{\\theta}_{2}\\)","definitionVi":"Công thức toán học của sự khúc xạ: n₁ sinθ₁ = n₂ sinθ₂.","memoryTipVi":"n = c / v là chiết suất tuyệt đối của môi trường."},{"term":"total internal reflection","termVi":"Hiện tượng phản xạ toàn phần","ipa":"/ˈtəʊ.təl ɪnˈtɜː.nəl/","definition":"reflection of light traveling through a medium with a large refractive index at a boundary of a medium with a low refractive index under conditions such that refraction cannot occur","definitionVi":"Toàn bộ ánh sáng bị phản xạ ngược lại môi trường chiết quang hơn (ứng dụng truyền dữ liệu trong CÁP QUANG!).","memoryTipVi":"2 điều kiện: n₁ > n₂ và θ₁ > θ_c."}],"assessments":[{"uid":"hsphys.ch16.sec02.q004","sourceId":"fs-id1167065681590","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"The refractive index of ethanol is 1.36. What is the speed of light in ethanol?","images":[],"choices":[{"label":"a","text":"2.25×108 m/s"},{"label":"b","text":"2.21×107 m/s"},{"label":"c","text":"2.25×109 m/s"},{"label":"d","text":"2.21×108 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec02.q009","sourceId":"fs-id1167065681590","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"The refractive index of ethanol is 1.36. What is the speed of light in ethanol?","images":[],"choices":[{"label":"a","text":"2.25×108 m/s"},{"label":"b","text":"2.21×107 m/s"},{"label":"c","text":"2.25×109 m/s"},{"label":"d","text":"2.21×108 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec02.q011","sourceId":"fs-id1167065874940","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"An optical fiber uses flint glass ( n = 1.66) clad with crown glass ( n = 1.52) . What is the critical angle?","images":[],"choices":[{"label":"a","text":"33.2°"},{"label":"b","text":"23.7°"},{"label":"c","text":"0.92 rad"},{"label":"d","text":"1.16 rad"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec02.q012","sourceId":"fs-id1167065919828","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Suppose this figure represents a ray of light going from air ( n = 1.0003) through crown glass ( n = 1.52) into water, similar to a beam of light going into a fish tank.\nCalculate the amount the ray is displaced by the glass (Δx), given that the incident angle is 40.0° and the glass is 1.00 cm thick.","images":[{"sourceId":"fs-id1164566861565","filename":"CNX_HSPhysics_16_02_Crown_img.jpg","relativePath":"media/CNX_HSPhysics_16_02_Crown_img.jpg","alt":"An image is shown with a ray going into a medium. The incident ray has an angle labeled theta 1 and it splits into two rays as it hits the first horizon labeled en 1. The ray on the bottom is represented by a solid line and starts with an angle labeled theta two and the ray continues through a medium labeled en 2. When it encounters a horizon labeled en 3, the angle of theta 2 is on top of the horizon and theta 3 is under the horizon. The ray on top is represented by a dashed line. It continues straight from the incident ray until it hits horizon en 3. After the ray enters en 3, the angle of theta 3 is below the horizon. A distance of delta x is marked between the two rays at the bottom of the second medium."}],"choices":[{"label":"a","text":"0.839 cm"},{"label":"b","text":"0.619 cm"},{"label":"c","text":"0.466 cm"},{"label":"d","text":"0.373 cm"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec02.q013","sourceId":"fs-id1167065952773","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What does c represent in the equation\n\\(n = \\frac{c}{v}\\) ?","images":[],"choices":[{"label":"a","text":"the critical angle"},{"label":"b","text":"the refractive index"},{"label":"c","text":"the speed of light in a vacuum"},{"label":"d","text":"the speed of light in a transparent material"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec02.q014","sourceId":"fs-id1167064743825","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What is the term for the minimum angle at which a light ray is reflected back into a material and cannot pass into the surrounding medium?","images":[],"choices":[{"label":"a","text":"critical angle"},{"label":"b","text":"incident angle"},{"label":"c","text":"angle of refraction"},{"label":"d","text":"angle of reflection"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec02.q015","sourceId":"eip-id1166849937173","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Consider these indices of refraction: glass: 1.52, air: 1.0003, water: 1.333. Put these materials in order from the one in which the speed of light is fastest to the one in which it is slowest.","images":[],"choices":[{"label":"a","text":"The speed of light in water > the speed of light in air > the speed of light in glass."},{"label":"b","text":"The speed of light in glass > the speed of light in water > the speed of light in air."},{"label":"c","text":"The speed of light in air > the speed of light in water > the speed of light in glass."},{"label":"d","text":"The speed of light in glass > the speed of light in air > the speed of light in water."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec02.q018","sourceId":"fs-id1167065014008","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Water floats on a liquid called carbon tetrachloride . The two liquids do not mix. A light ray passing from water into carbon tetrachloride has an incident angle of 45.0° and an angle of refraction of 40.1°. If the index of refraction of water is 1.33, what is the index of refraction of carbon tetrachloride?","images":[],"choices":[{"label":"a","text":"1.60"},{"label":"b","text":"1.49"},{"label":"c","text":"1.21"},{"label":"d","text":"1.46"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec02.q019","sourceId":"fs-id1167065961278","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Describe what happens to a light ray when it is refracted. Include in your explanation comparison of angles, comparison of refractive indices, and the term normal .","images":[],"choices":[{"label":"a","text":"When a ray of light goes from one medium to another medium with a different refractive index, the ray changes its path as a result of interference. The angle between the ray and the normal (the line perpendicular to the surfaces of the two media) is greater in the medium with the greater refractive index."},{"label":"b","text":"When a ray of light goes from one medium to another medium with a different refractive index, the ray changes its path as a result of refraction. The angle between the ray and the normal (the line perpendicular to the surfaces of the two media) is less in the medium with the greater refractive index."},{"label":"c","text":"When a ray of light goes from one medium to another medium with a different refractive index, the ray does not change its path. The angle between the ray and the normal (the line parallel to the surfaces of the two media) is the same in both media."},{"label":"d","text":"When a ray of light goes from one medium to another medium with a different refractive index, the ray changes its path as a result of refraction. The angle between the ray and the normal (the line perpendicular to the surfaces of the two media) is less in the medium with the lower refractive index."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec02.q020","sourceId":"fs-id1167065086638","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"A scuba diver training in a pool looks at his instructor, as shown in this figure. The angle between the ray in the water and the normal to the water is 25°.\nWhat angle does the ray make from the instructor’s face with the normal to the water ( n = 1.33) at the point where the ray enters? Assume n = 1.00 for air.","images":[{"sourceId":"eip-idm377810576","filename":"CNX_HSPhysics_16_02_Scuba_img.jpg","relativePath":"media/CNX_HSPhysics_16_02_Scuba_img.jpg","alt":"The figure depicts an instructor looking down at a scuba diver within a body of water."}],"choices":[{"label":"a","text":"68°"},{"label":"b","text":"25°"},{"label":"c","text":"19°"},{"label":"d","text":"34°"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec02.q021","sourceId":"fs-id1167064720505","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"Describe total internal reflection. Include a definition of the critical angle and how it is related to total internal reflection. Also, compare the indices of refraction of the interior material and the surrounding material.","images":[],"choices":[{"label":"a","text":"When the interior material has a smaller index of refraction than the surrounding material, the incident ray may approach the boundary at an angle (called the critical angle ) such that the refraction angle is 90° . The refracted ray cannot leave the interior, so it is reflected back inside and total internal reflection occurs."},{"label":"b","text":"When the interior material has a smaller index of refraction than the surrounding material, the incident ray may approach the boundary at an angle (called the critical angle ) such that the refraction angle is less than 90° . The refracted ray cannot leave the interior, so it is reflected back inside and total internal reflection occurs."},{"label":"c","text":"When the interior material has the same index of refraction as the surrounding material, the incident ray approaches the boundary at an angle (called the critical angle ) such that the refraction angle is less than 90° . The refracted ray cannot leave the interior, so it is reflected back inside and total internal reflection occurs."},{"label":"d","text":"When the interior material has a greater index of refraction than the surrounding material, the incident ray may approach the boundary at an angle (called the critical angle ) such that the refraction angle is 90° . The refracted ray cannot leave the interior, so it is reflected back inside and total internal reflection occurs."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":4,"subsectionCount":2,"workedExampleCount":3,"snapLabCount":1,"glossaryCount":8,"assessmentCount":11}},{"uid":"hsphys.ch16.sec03","moduleId":"m54361","number":"16.3","slug":"lenses","title":"Lenses","isIntroduction":false,"learningObjectives":["Describe and predict image formation and magnification as a consequence of refraction through convex and concave lenses, use ray diagrams to confirm image formation, and discuss how these properties of lenses determine their applications","Explain how the human eye works in terms of geometric optics","Perform calculations, based on the thin-lens equation, to determine image and object distances, focal length, and image magnification, and use these calculations to confirm values determined from ray diagrams"],"bilingualGuide":{"notebookSummaryVi":"Thấu kính hội tụ (Convex/Converging, f > 0), Thấu kính phân kỳ (Concave/Diverging, f < 0), Công thức thấu kính mỏng và Quang sai.","wordProblemCues":[{"phraseEn":"thin-lens equation","meaningVi":"Công thức thấu kính mỏng","mathNotation":"1/f = 1/d_o + 1/d_i"}],"commonTrapsVi":["⚠️ False Friend hình dạng: Gương LÕM là hội tụ nhưng Thấu kính LÕM lại là PHÂN KỲ!"]},"keyEquations":[{"name":"power and focal length","formula":"\\(P = \\frac{1}{f}\\)"},{"name":"mirror/lens (or thin-lens) equation","formula":"\\(\\frac{1}{f} = \\frac{1}{{d}_{i}} + \\frac{1}{{d}_{o}}\\)"},{"name":"rearranged mirror/lens equation","formula":"\\({d}_{i} = \\frac{f{d}_{o}}{{d}_{o} - f}\\)"},{"name":"magnification equation","formula":"\\(m = \\frac{{h}_{i}}{{h}_{o}} = - \\frac{{d}_{i}}{{d}_{o}}\\)"}],"subsections":[{"uid":"hsphys.ch16.sec03.sub01","title":"Characteristics of Lenses","summaryVi":"Thấu kính hội tụ (Convex/Converging, f > 0), Thấu kính phân kỳ (Concave/Diverging, f < 0), Công thức thấu kính mỏng và Quang sai. Thuật ngữ trọng tâm trong mục này: aberration (Quang sai (Lỗi méo ảnh quang học)), chromatic aberration (Sắc sai (Viền màu ở mép ảnh)), concave lens (Thấu kính lõm (Phân kỳ)), converging lens (Thấu kính hội tụ (Thấu kính lồi)).","paragraphs":["Lenses are found in a huge array of optical instruments, ranging from a simple magnifying glass to the eye to a camera’s zoom lens. In this section, we use the law of refraction to explore the properties of lenses and how they form images.","Some of what we learned in the earlier discussion of curved mirrors also applies to the study of lenses. Concave, convex, focal point F, and focal length f have the same meanings as before, except each measurement is made from the center of the lens instead of the surface of the mirror. The convex lens shown in Figure 16.3 has been shaped so that all light rays that enter it parallel to its central axis cross one another at a single point on the opposite side of the lens. The central axis, or axis, is defined to be a line normal to the lens at its center. Such a lens is called a converging lens because of the converging effect it has on light rays. An expanded view of the path of one ray through the lens is shown in Figure 16.3 to illustrate how the ray changes direction both as it enters and as it leaves the lens. Because the index of refraction of the lens is greater than that of air, the ray moves toward the perpendicular as it enters and away from the perpendicular as it leaves. (This is in accordance with the law of refraction.) As a result of the shape of the lens, light is thus bent toward the axis at both surfaces.","Note that rays from a light source placed at the focal point of a converging lens emerge parallel from the other side of the lens. You may have heard of the trick of using a converging lens to focus rays of sunlight to a point. Such a concentration of light energy can produce enough heat to ignite paper.","Figure 16.3 shows a concave lens and the effect it has on rays of light that enter it parallel to its axis (the path taken by ray 2 in the figure is the axis of the lens). The concave lens is a diverging lens because it causes the light rays to bend away (diverge) from its axis. In this case, the lens has been shaped so all light rays entering it parallel to its axis appear to originate from the same point, F, defined to be the focal point of a diverging lens. The distance from the center of the lens to the focal point is again called the focal length , or “ ƒ ,” of the lens. Note that the focal length of a diverging lens is defined to be negative. An expanded view of the path of one ray through the lens is shown in Figure 16.3 to illustrate how the shape of the lens, together with the law of refraction, causes the ray to follow its particular path and diverge.","The power, P , of a lens is very easy to calculate. It is simply the reciprocal of the focal length, expressed in meters","The units of power are diopters, D, which are expressed in reciprocal meters. If the focal length is negative, as it is for the diverging lens in Figure 16.3, then the power is also negative.","In some circumstances, a lens forms an image at an obvious location, such as when a movie projector casts an image onto a screen. In other cases, the image location is less obvious. Where, for example, is the image formed by eyeglasses? We use ray tracing for thin lenses to illustrate how they form images, and we develop equations to describe the image-formation quantitatively. These are the rules for ray tracing:","Consider an object some distance away from a converging lens, as shown in Figure 16.3. To find the location and size of the image formed, we trace the paths of select light rays originating from one point on the object. In this example, the originating point is the top of a woman’s head. Figure 16.3 shows three rays from the top of the object that can be traced using the ray-tracing rules just listed. Rays leave this point traveling in many directions, but we concentrate on only a few, which have paths that are easy to trace. The first ray is one that enters the lens parallel to its axis and passes through the focal point on the other side (rule 1). The second ray passes through the center of the lens without changing direction (rule 3). The third ray passes through the nearer focal point on its way into the lens and leaves the lens parallel to its axis (rule 4). All rays that come from the same point on the top of the person’s head are refracted in such a way as to cross at the same point on the other side of the lens. The image of the top of the person’s head is located at this point. Rays from another point on the object, such as the belt buckle, also cross at another common point, forming a complete image, as shown. Although three rays are traced in Figure 16.3, only two are necessary to locate the image. It is best to trace rays for which there are simple ray-tracing rules. Before applying ray tracing to other situations, let us consider the example shown in Figure 16.3 in more detail.","The image formed in Figure 16.3 is a real image—meaning, it can be projected. That is, light rays from one point on the object actually cross at the location of the image and can be projected onto a screen, a piece of film, or the retina of an eye.","In Figure 16.3, the object distance, d o , is greater than f. Now we consider a ray diagram for a convex lens where d o < f , and another diagram for a concave lens.","This animation shows you how the image formed by a convex lens changes as you change object distance, curvature radius, refractive index, and diameter of the lens. To begin, choose Principal Rays in the upper left menu and then try varying some of the parameters indicated at the upper center. Show Help supplies a few helpful labels.","The examples in Figure 16.3 and Figure 16.3 represent the three possible cases—case 1, case 2, and case 3—summarized in the table below. In the table, m is magnification; the other symbols have the same meaning as they did for curved mirrors.","Image formation by lenses can also be calculated from simple equations. We learn how these calculations are carried out near the end of this section.","Some common applications of lenses with which we are all familiar are magnifying glasses, eyeglasses, cameras, microscopes, and telescopes. We take a look at the latter two examples, which are the most complex. We have already seen the design of a telescope that uses only mirrors in Figure 16.1. Figure 16.3 shows the design of a telescope that uses two lenses. Part (a) of the figure shows the design of the telescope used by Galileo. It produces an upright image, which is more convenient for many applications. Part (b) shows an arrangement of lenses used in many astronomical telescopes. This design produces an inverted image, which is less of a problem when viewing celestial objects.","Figure 16.3 shows the path of light through a typical microscope. Microscopes were first developed during the early 1600s by eyeglass makers in the Netherlands and Denmark. The simplest compound microscope is constructed from two convex lenses, as shown schematically in Figure 16.3. The first lens is called the objective lens ; it has typical magnification values from 5 \\(\\times\\) to 100 \\(\\times\\) . In standard microscopes, the objectives are mounted such that when you switch between them, the sample remains in focus. Objectives arranged in this way are described as parfocal . The second lens, the eyepiece , also referred to as the ocular , has several lenses that slide inside a cylindrical barrel. The focusing ability is provided by the movement of both the objective lens and the eyepiece. The purpose of a microscope is to magnify small objects, and both lenses contribute to the final magnification. In addition, the final enlarged image is produced in a location far enough from the observer to be viewed easily because the eye cannot focus on objects or images that are too close.","Real lenses behave somewhat differently from how they are modeled using rays diagrams or the thin-lens equations. Real lenses produce aberrations. An aberration is a distortion in an image. There are a variety of aberrations that result from lens size, material, thickness, and the position of the object. One common type of aberration is chromatic aberration , which is related to color. Because the index of refraction of lenses depends on color, or wavelength, images are produced at different places and with different magnifications for different colors. The law of reflection is independent of wavelength, so mirrors do not have this problem. This result is another advantage for the use of mirrors in optical systems such as telescopes.","Figure 16.3(a) shows chromatic aberration for a single convex lens, and its partial correction with a two-lens system. The index of refraction of the lens increases with decreasing wavelength, so violet rays are refracted more than red rays, and are thus focused closer to the lens. The diverging lens corrects this in part, although it is usually not possible to do so completely. Lenses made of different materials and with different dispersions may be used. For example, an achromatic doublet consisting of a converging lens made of crown glass in contact with a diverging lens made of flint glass can reduce chromatic aberration dramatically (Figure 16.3(b))."],"figures":[{"sourceId":"fs-id1167065809698","filename":"CNX_HSPhysics_16_03_ConvexLens.jpg","relativePath":"media/CNX_HSPhysics_16_03_ConvexLens.jpg","alt":"A drawing on the left side of the figure depicts a convex lens with three parallel light rays (labeled 1, 2, and 3 from top to bottom) passing through the lens from the left and converging to the right of the lens at F. After passing through F, the light rays are flipped from top to bottom (3, 2, 1). The figure on the right is an expanded view of the figure on the left."},{"sourceId":"fs-id1167064634524","filename":"CNX_HSPhysics_16_03_ConcaveL.jpg","relativePath":"media/CNX_HSPhysics_16_03_ConcaveL.jpg","alt":"In this schematic, parallel rays of light (rays 1, 2, and 3, top to bottom) enter a convex lens and diverge away from the axis. These diverging rays are labeled 1, 2, and 3 (top to bottom). Another schematic shows an expanded view of ray 1."},{"sourceId":"fs-id1167064549938","filename":"CNX_HSPhysics_16_03_ConvexL2.jpg","relativePath":"media/CNX_HSPhysics_16_03_ConvexL2.jpg","alt":"This series of drawings shows a woman standing to the left of a lens. Rays originate from the top of her head and pass through the lens at various angles to create a real image on the other side of the lens."},{"sourceId":"fs-id1167065945296","filename":"CNX_HSPhysics_16_03_ConcaveVex.jpg","relativePath":"media/CNX_HSPhysics_16_03_ConcaveVex.jpg","alt":"These two schematics, (a) and (b), are a visual depiction of cases 1 through 3 presented in Three Types of Images Formed by Lenses."},{"sourceId":"fs-id1167065897963","filename":"CNX_HSPhysics_16_03_Telescope.jpg","relativePath":"media/CNX_HSPhysics_16_03_Telescope.jpg","alt":"In view (a), moving from left to right, there is a tree (which is a real final image), an objective, an eyepiece, and an eye. Incoming parallel rays of light pass through the objective (which is convex) and the eyepiece (which is concave) to the eye. In view (b), moving from left to right, there is an inverted tree (which is a magnified final image), an objective and an eyepiece (both of which are convex), and an eye. Incoming rays of light pass through the first objective and converge, then pass through the second lens (the eyepiece) to the eye."},{"sourceId":"fs-id1167065878796","filename":"CNX_HSPhysics_16_03_Microscope.jpg","relativePath":"media/CNX_HSPhysics_16_03_Microscope.jpg","alt":"The schematic depicts the inner workings of a microscope."},{"sourceId":"fs-id1167065761952","filename":"CNX_HSPhysics_16_03_Aberration.jpg","relativePath":"media/CNX_HSPhysics_16_03_Aberration.jpg","alt":"View (a) is a sketch of a convex lens. White light, originating at a single point to the left, diverges and enters the lens. The rays pass through the lens and refract to produce a chromatic aberration. View (b) is a sketch of a multilense system in which parallel rays of white light to the left of the system pass through a convex lens, then a concave lens, to converge at a point that corrects the chromatic aberration."}],"tables":[{"sourceId":"Table_16_03","headers":["Type","Formed When","Image Type","d i","M"],"rows":[["Case 1","f positive, d o > f","Real","Positive","Negative m >, <, or = ‒1"],["Case 2","f positive, d o < f","Virtual","Negative","Positive m > 1"],["Case 3","f negative","Virtual","Negative","Positive m < 1"]]}]},{"uid":"hsphys.ch16.sec03.sub02","title":"Physics of the Eye","summaryVi":"Thấu kính hội tụ (Convex/Converging, f > 0), Thấu kính phân kỳ (Concave/Diverging, f < 0), Công thức thấu kính mỏng và Quang sai. Thuật ngữ trọng tâm trong mục này: convex lens (Thấu kính lồi (Hội tụ)).","paragraphs":["The eye is perhaps the most interesting of all optical instruments. It is remarkable in how it forms images and in the richness of detail and color they eye can detect. However, our eyes commonly need some correction to reach what is called normal vision, but should be called ideal vision instead. Image formation by our eyes and common vision correction are easy to analyze using geometric optics. Figure 16.3 shows the basic anatomy of the eye. The cornea and lens form a system that, to a good approximation, acts as a single thin lens. For clear vision, a real image must be projected onto the light-sensitive retina, which lies at a fixed distance from the lens. The lens of the eye adjusts its power to produce an image on the retina for objects at different distances. The center of the image falls on the fovea, which has the greatest density of light receptors and the greatest acuity (sharpness) in the visual field. There are no receptors at the place where the optic nerve meets the eye, which is called the blind spot . An image falling on this spot cannot be seen. The variable opening (or pupil) of the eye along with chemical adaptation allows the eye to detect light intensities from the lowest observable to 10 10 times greater (without damage). Ten orders of magnitude is an incredible range of detection. Our eyes perform a vast number of functions, such as sense direction, movement, sophisticated colors, and distance. Processing of visual nerve impulses begins with interconnections in the retina and continues in the brain. The optic nerve conveys signals received by the eye to the brain.","Refractive indices are crucial to image formation using lenses. the table below shows refractive indices relevant to the eye. The biggest change in the refractive index—and the one that causes the greatest bending of rays—occurs at the cornea rather than the lens. The ray diagram in Figure 16.3 shows image formation by the cornea and lens of the eye. The rays bend according to the refractive indices provided in the table below. The cornea provides about two-thirds of the magnification of the eye because the speed of light changes considerably while traveling from air into the cornea. The lens provides the remaining magnification needed to produce an image on the retina. The cornea and lens can be treated as a single thin lens, although the light rays pass through several layers of material (such as the cornea, aqueous humor, several layers in the lens, and vitreous humor), changing direction at each interface. The image formed is much like the one produced by a single convex lens. This result is a case 1 image. Images formed in the eye are inverted, but the brain inverts them once more to make them seem upright.","As noted, the image must fall precisely on the retina to produce clear vision—that is, the image distance, d i , must equal the lens-to-retina distance. Because the lens-to-retina distance does not change, d i must be the same for objects at all distances. The eye manages to vary the distance by varying the power (and focal length) of the lens to accommodate for objects at various distances. In Figure 16.3, you can see the small ciliary muscles above and below the lens that change the shape of the lens and, thus, the focal length.","The need for some type of vision correction is very common. Common vision defects are easy to understand, and some are simple to correct. Figure 16.3 illustrates two common vision defects. Nearsightedness, or myopia, is the inability to see distant objects clearly while close objects are in focus. The nearsighted eye overconverges the nearly parallel rays from a distant object, and the rays cross in front of the retina. More divergent rays from a close object are converged on the retina, producing a clear image. Farsightedness, or hyperopia, is the inability to see close objects clearly whereas distant objects may be in focus. A farsighted eye does not converge rays from a close object sufficiently to make the rays meet on the retina. Less divergent rays from a distant object can be converged for a clear image.","Because the nearsighted eye overconverges light rays, the correction for nearsightedness involves placing a diverging spectacle lens in front of the eye. This lens reduces the power of an eye that has too short a focal length (Figure 16.5(a)). Because the farsighted eye underconverges light rays, the correction for farsightedness is to place a converging spectacle lens in front of the eye. This lens increases the power of an eye that has too long a focal length (Figure 16.5(b))."],"figures":[{"sourceId":"fs-id1167063535758","filename":"CNX_HSPhysics_16_03_Eye.jpg","relativePath":"media/CNX_HSPhysics_16_03_Eye.jpg","alt":"This schematic is a cross-section of the various parts of the eye."},{"sourceId":"fs-id1167067314264","filename":"CNX_HSPhysics_16_03_Eye2.jpg","relativePath":"media/CNX_HSPhysics_16_03_Eye2.jpg","alt":"This schematic shows a cross-section of an eyeball. An upright tree is to the left of the eye. Rays 1 and 2 come from the top of the tree; rays 3 and 4 originate from the bottom of the tree. The rays enter the eyeball, pass through the components of the eye, and produce an image of an inverted tree."},{"sourceId":"fs-id1167067054733","filename":"CNX_HSPhysics_16_03_Eye3.jpg","relativePath":"media/CNX_HSPhysics_16_03_Eye3.jpg","alt":"View (a) shows schematic cross-sections of the eye indicative of myopia. View (b) show schematic cross-sections of the eye indicative of hyperopia."},{"sourceId":"fs-id1167067052594","filename":"CNX_HSPhysics_16_03_Eye4.jpg","relativePath":"media/CNX_HSPhysics_16_03_Eye4.jpg","alt":"View (a) shows a schematic cross-section of the eye and a concave lens that corrects for nearsightedness. View (b) shows a schematic cross-section of the eye and a convex lens that corrects for farsightedness."}],"tables":[{"sourceId":"Table_16_04","headers":["Material","Index of Refraction"],"rows":[["Water","1.33"],["Air","1.00"],["Cornea","1.38"],["Aqueous humor","1.34"],["Lens","1.41 average *"],["Vitreous humor","1.34"]]}]},{"uid":"hsphys.ch16.sec03.sub03","title":"Calculations Using Lens Equations","summaryVi":"Thấu kính hội tụ (Convex/Converging, f > 0), Thấu kính phân kỳ (Concave/Diverging, f < 0), Công thức thấu kính mỏng và Quang sai.","paragraphs":["As promised, there are no new equations to memorize. We can use equations already presented for solving problems involving curved mirrors. Careful analysis allows you to apply these equations to lenses. Here are the equations you need","where P is power, expressed in reciprocal meters (m –1 ) rather than diopters (D), and f is focal length, expressed in meters (m). You also need","where, as before, d o and d i are object distance and image distance, respectively. Remember, this equation is usually more useful if rearranged to solve for one of the variables. For example,","The equations for magnification, m , are also the same as for mirrors","where h i and h o are the image height and object height, respectively. Remember, also, that a negative d i value indicates a virtual image and a negative h i value indicates an inverted image.","These are the steps to follow when solving a lens problem:","All problems will be solved by one or more of the equations just presented, with ray tracing used only for general analysis of the problem. The steps then simplify to the following:","Here are some worked examples:"],"figures":[],"tables":[]},{"uid":"hsphys.ch16.sec03.sub04","title":"Performance Task","summaryVi":"Thấu kính hội tụ (Convex/Converging, f > 0), Thấu kính phân kỳ (Concave/Diverging, f < 0), Công thức thấu kính mỏng và Quang sai.","paragraphs":["In this performance task, you will investigate the lens-like properties of a clear bottle.","Instructions"],"figures":[],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch16.sec03.ex01","number":"16.3.1","title":"The Power of a Magnifying Glass","problem":"","problemImages":[],"strategy":"The Sun is so far away that its rays are nearly parallel when they reach Earth. The magnifying glass is a convex (or converging) lens, focusing the nearly parallel rays of sunlight. Thus, the focal length of the lens is the distance from the lens to the spot, and its power, in diopters (D), is the inverse of this distance (in reciprocal meters).","solution":"The focal length of the lens is the distance from the center of the lens to the spot, which we know to be 8.00 cm. Thus,\n\\(f = 8.00\\,\\text{cm}\\text{.}\\)\nTo find the power of the lens, we must first convert the focal length to meters; then, we substitute this value into the equation for power.\n\\(P = \\frac{1}{f} = \\frac{1}{0.0800\\,\\text{m}} = 12.5\\,\\text{D}\\)","solutionImages":[],"solutionTables":[],"discussion":"This result demonstrates a relatively powerful lens. Remember that the power of a lens in diopters should not be confused with the familiar concept of power in watts."},{"uid":"hsphys.ch16.sec03.ex02","number":"16.3.2","title":"Image Formation by a Convex Lens","problem":"A clear glass light bulb is placed 0.75 m from a convex lens with a 0.50 m focal length, as shown in Figure 16.3. Use ray tracing to get an approximate location for the image. Then, use the mirror/lens equations to calculate (a) the location of the image and (b) its magnification. Verify that ray tracing and the thin-lens and magnification equations produce consistent results.\nA light bulb placed 0.75 m from a lens with a 0.50 m focal length produces a real image on a poster board, as discussed in the previous example. Ray tracing predicts the image location and size.","problemImages":[{"sourceId":"fs-id1167064914709","filename":"CNX_HSPhysics_16_03_Example.jpg","relativePath":"media/CNX_HSPhysics_16_03_Example.jpg","alt":"The example is illustrated and depicts values of f = 0.50 m, do = 0.75 m, and di = 1.50 m."}],"strategy":"Because the object is placed farther away from a converging lens than the focal length of the lens, this situation is analogous to the one illustrated in the previous figure of a series of drawings showing a woman standing to the left of a lens. Ray tracing to scale should produce similar results for d i . Numerical solutions for d i and m can be obtained using the thin-lens and magnification equations, noting that d o = 0.75 m and f = 0.50 m.","solution":"The ray tracing to scale in Figure 16.3 shows two rays from a point on the bulb’s filament crossing about 1.50 m on the far side of the lens. Thus, the image distance, d i , is about 1.50 m. Similarly, the image height based on ray tracing is greater than the object height by about a factor of two, and the image is inverted. Thus, m is about –2. The minus sign indicates the image is inverted. The lens equation can be rearranged to solve for d i from the given information.\n\\({d}_{i} = \\frac{f{d}_{o}}{{d}_{o} - f} = \\frac{(0.50)(0.75)}{0.75–0.50} = 1.5\\,\\text{m}\\)\nNow, we use \\(\\frac{{d}_{i}}{{d}_{o}}\\) to find m .\n\\(m = - \\frac{{d}_{i}}{{d}_{o}} = - \\frac{1.5}{0.75} = - 2.0\\)","solutionImages":[],"solutionTables":[],"discussion":"Note that the minus sign causes the magnification to be negative when the image is inverted. Ray tracing and the use of the lens equation produce consistent results. The thin-lens equation gives the most precise results, and is limited only by the accuracy of the given information. Ray tracing is limited by the accuracy with which you draw, but it is highly useful both conceptually and visually."},{"uid":"hsphys.ch16.sec03.ex03","number":"16.3.3","title":"Image Formation by a Concave Lens","problem":"Suppose an object, such as a book page, is held 6.50 cm from a concave lens with a focal length of –10.0 cm. Such a lens could be used in eyeglasses to correct pronounced nearsightedness. What magnification is produced?","problemImages":[],"strategy":"This example is identical to the preceding one, except that the focal length is negative for a concave or diverging lens. The method of solution is therefore the same, but the results are different in important ways.","solution":"\\({d}_{i} = \\frac{f{d}_{o}}{{d}_{o}\\text{-}f} = \\frac{(\\text{-}10.0)(6.50)}{6.50 - (\\text{-}10.0)} = - 3.94\\,\\text{cm}\\)\nNow the magnification equation can be used to find the magnification, m , because both d i and d o are known. Entering their values gives\n\\(m = - \\frac{{d}_{i}}{{d}_{o}} = - \\frac{- 3.94}{6.50} = 0.606.\\)","solutionImages":[],"solutionTables":[],"discussion":"A number of results in this example are true of all case 3 images. Magnification is positive (as calculated), meaning the image is upright. The magnification is also less than one, meaning the image is smaller than the object—in this case, a little more than half its size. The image distance is negative, meaning the image is on the same side of the lens as the object. The image is virtual. The image is closer to the lens than the object, because the image distance is smaller in magnitude than the object distance. The location of the image is not obvious when you look through a concave lens. In fact, because the image is smaller than the object, you may think it is farther away; however, the image is closer than the object—a fact that is useful in correcting nearsightedness."}],"snapLabs":[{"uid":"hsphys.ch16.sec03.lab01","title":"Focal Length","text":"Temperature extremes—Very hot or very cold temperatures are encountered in this lab that can cause burns. Use protective mitts, eyewear, and clothing when handling very hot or very cold objects. Notify your teacher immediately of any burns.\nEYE SAFETY—Looking at the Sun directly can cause permanent eye damage. Do not look at the Sun through any lens.\nSeveral lenses\nA sheet of white paper\nA ruler or tape measure\nInstructions\nProcedure\nFind several lenses and determine whether they are converging or diverging. In general, those that are thicker near the edges are diverging and those that are thicker near the center are converging.\nOn a bright, sunny day take the converging lenses outside and try focusing the sunlight onto a sheet of white paper.\nDetermine the focal lengths of the lenses. Have one partner slowly move the lens toward and away from the paper until you find the distance at which the light spot is at its brightest. Have the other partner measure the distance from the lens to the bright spot. Be careful, because the paper may start to burn, depending on the type of lens.\nTrue or false—The bright spot that appears in focus on the paper is an image of the Sun.\nTrue\nFalse","images":[]}],"tipsAndFeatures":[],"summaryPoints":["The characteristics of images formed by concave and convex lenses can be predicted using ray tracing. Characteristics include real versus virtual, inverted versus upright, and size.","The human eye and corrective lenses can be explained using geometric optics.","Characteristics of images formed by lenses can be calculated using the mirror/lens equation."],"glossary":[{"term":"aberration","termVi":"Quang sai (Lỗi méo ảnh quang học)","ipa":"/ˌæb.əˈreɪ.ʃən/","definition":"a distortion in an image produced by a lens","definitionVi":"Sự nhòe hoặc méo hình ảnh do thấu kính/gương không hội tụ mọi tia về đúng một điểm.","memoryTipVi":"Ống kính máy ảnh đắt tiền ghép nhiều thấu kính để khử quang sai."},{"term":"chromatic aberration","termVi":"Sắc sai (Viền màu ở mép ảnh)","ipa":"/krəʊˈmæt.ɪk/","definition":"an aberration related to color","definitionVi":"Lỗi viền màu quanh ảnh tạo bởi thấu kính do hiện tượng tán sắc (mỗi màu có tiêu cự hơi khác nhau).","memoryTipVi":"Gương cầu không bị sắc sai — đó là lý do kính thiên văn khổng lồ dùng gương!"},{"term":"concave lens","termVi":"Thấu kính lõm (Phân kỳ)","ipa":"/ˌkɒnˈkeɪv lenz/","definition":"a lens that causes light rays to diverge from the central axis","definitionVi":"Tên hình dạng của thấu kính phân kỳ (f < 0).","memoryTipVi":"Luôn cho ảnh ảo cùng chiều, nhỏ hơn vật."},{"term":"converging lens","termVi":"Thấu kính hội tụ (Thấu kính lồi)","ipa":"/kənˈvɜː.dʒɪŋ lenz/","definition":"a convex lens","definitionVi":"Thấu kính dày ở giữa, mỏng ở rìa — làm hội tụ chùm tia sáng (f > 0).","memoryTipVi":"Dùng làm kính lúp, chữa viễn thị."},{"term":"convex lens","termVi":"Thấu kính lồi (Hội tụ)","ipa":"/ˌkɒnˈveks lenz/","definition":"a lens that causes light rays to converge toward the central axis","definitionVi":"Tên hình dạng của thấu kính hội tụ (f > 0).","memoryTipVi":"⚠️ Cẩn thận ngược với Gương: Gương lồi là phân kỳ, còn Thấu kính lồi là HỘI TỤ!"},{"term":"diverging lens","termVi":"Thấu kính phân kỳ (Thấu kính lõm)","ipa":"/daɪˈvɜː.dʒɪŋ lenz/","definition":"a concave lens","definitionVi":"Thấu kính mỏng ở giữa, dày ở rìa — làm loe rộng chùm tia sáng (f < 0), luôn cho ảnh ảo nhỏ hơn vật.","memoryTipVi":"Dùng để chữa CẬN THỊ!"}],"assessments":[{"uid":"hsphys.ch16.sec03.q002","sourceId":"fs-id1167064876918","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Which part of the eye controls the amount of light that enters?","images":[],"choices":[{"label":"a","text":"the pupil"},{"label":"b","text":"the iris"},{"label":"c","text":"the cornea"},{"label":"d","text":"the retina"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec03.q006","sourceId":"fs-id1167064537035","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"If a lens produces a 5.00 -cm tall image of an 8.00 -cm -high object when placed 10.0 cm from the lens, what is the apparent image distance? Construct a ray diagram using paper, a pencil, and a ruler to confirm your calculation.","images":[],"choices":[{"label":"a","text":"-3.12 cm"},{"label":"b","text":"-6.25 cm"},{"label":"c","text":"3.12 cm"},{"label":"d","text":"6.25 cm"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec03.q007","sourceId":"fs-id1167065845902","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"An object is positioned in front of a lens with its base resting on the principal axis. Describe two rays that could be traced from the top of the object and through the lens that would locate the top of an image.","images":[],"choices":[{"label":"a","text":"A ray perpendicular to the axis and a ray through the center of the lens"},{"label":"b","text":"A ray parallel to the axis and a ray that does not pass through the center of the lens"},{"label":"c","text":"A ray parallel to the axis and a ray through the center of the lens"},{"label":"d","text":"A ray parallel to the axis and a ray that does not pass through the focal point"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec03.q009","sourceId":"eip-id1166851274528","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"For a concave lens, if the image distance, d i , is negative, where does the image appear to be with respect to the object?","images":[],"choices":[{"label":"a","text":"The image always appears on the same side of the lens."},{"label":"b","text":"The image appears on the opposite side of the lens."},{"label":"c","text":"The image appears on the opposite side of the lens only if the object distance is greater than the focal length."},{"label":"d","text":"The image appears on the same side of the lens only if the object distance is less than the focal length."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec03.q010","sourceId":"fs-id1167062377097","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"When you focus a camera, you adjust the distance of the lens from the film. If the camera lens acts like a thin lens, why can it not be kept at a fixed distance from the film for both near and distant objects?","images":[],"choices":[{"label":"a","text":"To focus on a distant object, you need to increase the image distance."},{"label":"b","text":"To focus on a distant object, you need to increase the focal length of the lens."},{"label":"c","text":"To focus on a distant object, you need to decrease the focal length of the lens."},{"label":"d","text":"To focus on a distant object, you may need to increase or decrease the focal length of the lens."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec03.q011","sourceId":"fs-id1167065967816","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Part A—How do the refractive indices of the cornea, aqueous humor, and the lens of the eye compare with the refractive index of air?\nPart B—How do the comparisons in part A explain how images are focused on the retina?","images":[],"choices":[{"label":"a","text":"(A) The cornea, aqueous humor, and lens of the eye have smaller refractive indices than air.\n(B) Rays entering the eye are refracted away from the central axis, which causes them to meet at the focal point on the retina."},{"label":"b","text":"(A) The cornea, aqueous humor, and lens of the eye have greater refractive indices than air.\n(B) Rays entering the eye are refracted away from the central axis, which causes them to meet at the focal point on the retina."},{"label":"c","text":"(A) The cornea, aqueous humor, and lens of the eye have smaller refractive indices than air.\n(B) Rays entering the eye are refracted toward the central axis, which causes them to meet at the focal point on the retina."},{"label":"d","text":"(A) The cornea, aqueous humor, and lens of the eye have greater refractive indices than air.\n(B) Rays entering the eye are refracted toward the central axis, which causes them to meet at the focal point on the retina."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec03.q013","sourceId":"fs-id1167064537035","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"If a lens produces a 5.00 -cm tall image of an 8.00 -cm -high object when placed 10.0 cm from the lens, what is the apparent image distance? Construct a ray diagram using paper, a pencil, and a ruler to confirm your calculation.","images":[],"choices":[{"label":"a","text":"-3.12 cm"},{"label":"b","text":"-6.25 cm"},{"label":"c","text":"3.12 cm"},{"label":"d","text":"6.25 cm"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec03.q014","sourceId":"fs-id1167064825834","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A cameras zoom lens has an adjustable focal length ranging from 80.0 to 200 mm . What is its range of powers?","images":[],"choices":[{"label":"a","text":"The lowest power is 0.05 D and the highest power is 0.125 D."},{"label":"b","text":"The lowest power is 0.08 D and the highest power is 0.20 D."},{"label":"c","text":"The lowest power is 5.00 D and the highest power is 12.5 D."},{"label":"d","text":"The lowest power is 80 D and the highest power is 200 D."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec03.q015","sourceId":"fs-id1167064538129","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Suppose a telephoto lens with a focal length of 200 mm is being used to photograph mountains 10.0 km away. (a) Where is the image? (b) What is the height of the image of a 1,000-m-high cliff on one of the mountains?","images":[],"choices":[{"label":"a","text":"(a) The image is 0.200 m on the same side of the lens. (b) The height of the image is  2.00 cm."},{"label":"b","text":"(a) The image is 0.200 m on the opposite side of the lens. (b) The height of the image is  2.00 cm."},{"label":"c","text":"(a) The image is 0.200 m on the opposite side of the lens. (b) The height of the image is +2.00 cm."},{"label":"d","text":"(a) The image is 0.100 m on the same side of the lens. (b) The height of the image is +2.00 cm."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec03.q016","sourceId":"fs-id1167064695462","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"For a given lens, what is the height of the image divided by the height of the object ( \\(\\frac{{h}_{i}}{{h}_{o}}\\) ) equal to?","images":[],"choices":[{"label":"a","text":"power"},{"label":"b","text":"focal length"},{"label":"c","text":"magnification"},{"label":"d","text":"radius of curvature"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec03.q017","sourceId":"fs-id1167065896743","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which part of the eye has the greatest density of light receptors?","images":[],"choices":[{"label":"a","text":"the lens"},{"label":"b","text":"the fovea"},{"label":"c","text":"the optic nerve"},{"label":"d","text":"the vitreous humor"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec03.q018","sourceId":"fs-id1167065937990","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What is the power of a lens with a focal length of 10 cm?","images":[],"choices":[{"label":"a","text":"10 m –1 , or 10 D"},{"label":"b","text":"10 cm –1 , or 10 D"},{"label":"c","text":"10 m, or 10 D"},{"label":"d","text":"10 cm, or 10 D"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec03.q020","sourceId":"fs-id1167062462416","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What are two equivalent terms for a lens that always causes light rays to bend away from the principal axis?","images":[],"choices":[{"label":"a","text":"a diverging lens or a convex lens"},{"label":"b","text":"a diverging lens or a concave lens"},{"label":"c","text":"a converging lens or a concave lens"},{"label":"d","text":"a converging lens or a convex lens"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec03.q021","sourceId":"fs-id1167064736580","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Define the term virtual image .","images":[],"choices":[{"label":"a","text":"A virtual image is an image that cannot be projected onto a screen."},{"label":"b","text":"A virtual image is an image that can be projected onto a screen."},{"label":"c","text":"A virtual image is an image that is formed on the opposite side of the lens from where the object is placed."},{"label":"d","text":"A virtual image is an image that is always bigger than the object."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec03.q025","sourceId":"fs-id1167065788863","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What is the magnification of a lens if it produces a 12-cm-high image of a 4 -cm -high object? The image is virtual and erect.","images":[],"choices":[{"label":"a","text":"\\(–3.00\\)"},{"label":"b","text":"\\(–\\frac{1}{3.00}\\)"},{"label":"c","text":"\\(\\frac{1}{3.00}\\)"},{"label":"d","text":"\\(3.00\\)"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch16.sec03.q026","sourceId":"fs-id1167065735893","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"The muscles that change the shape of the lens in the eyes have become weak, causing vision problems for a person. In particular, the muscles cannot pull hard enough on the edges of the lens to make it less convex.\nPart A—What condition does inability cause?\nPart B—Where are images focused with respect to the retina?\nPart C—Which type of lens corrects this person’s problem? Explain.","images":[],"choices":[{"label":"a","text":"Part A—This condition causes hyperopia.\nPart B—Images are focused between the lens and the retina.\nPart C—A converging lens gathers the rays slightly so they focus onto the retina."},{"label":"b","text":"Part A—This condition causes myopia.\nPart B—Images are focused between the lens and the retina.\nPart C—A converging lens gathers the rays slightly so they focus onto the retina."},{"label":"c","text":"Part A—This condition causes hyperopia.\nPart B—Images are focused between the lens and the retina.\nPart C—A diverging lens spreads the rays slightly so they focus onto the retina."},{"label":"d","text":"Part A—This condition causes myopia.\nPart B—Images are focused between the lens and the retina.\nPart C—A diverging lens spreads the rays slightly so they focus onto the retina."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":3,"keyEquationCount":4,"subsectionCount":4,"workedExampleCount":3,"snapLabCount":1,"glossaryCount":6,"assessmentCount":16}}],"summary":{"totalSections":4,"totalKeyEquations":12,"totalWorkedExamples":8,"totalSnapLabs":3,"totalGlossaryTerms":26,"totalAssessments":41,"referencedMediaCount":38},"qualityGate":{"passed":true,"checkedUids":65,"errors":[],"warnings":[]}};
